window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q15"]=window.__LIBQ["the-gioi-hoan-my"]["q15"]||{};window.__LIBQ["the-gioi-hoan-my"]["q15"]["artifacts"]={"updatedAt":"2026-07-26","count":86,"artifacts":[{"id":"dao-cau-tram-tien-dai","name":"Dao cầu Trảm Tiên đài","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo tàn khuyết","phanLoaiPhu":"Mảnh tàn khuyết","phamCap":"Không rõ","soHuu":[],"trangThai":"Tàn khuyết","blurb":"Dao cầu gắn với Trảm Tiên đài, đã rơi mất một góc hóa thành chùm sáng. Mảnh sáng có khả năng xuyên hư không và phá thủng nhiều binh khí.","detail":"Một góc tàn khuyết từ dao cầu biến thành thần mang tự đổi hướng khi bị truy bắt. Nó xuyên thủng đáy Kim bì hồ lô, chém phá thuẫn và mâu, thậm chí làm người tham gia ngăn chặn bị thương ở tay.","uyLuc":"Mảnh thần mang có sức xuyên phá cực mạnh, đủ xuyên thủng nhiều pháp bảo dùng để ngăn chặn.","dacDiem":"Một góc của dao cầu rơi khỏi Trảm Tiên đài và tồn tại dưới dạng chùm sáng linh hoạt.","congNang":["Xuyên qua hư không và tự đổi hướng để thoát khỏi sự ngăn chặn.","Chém thủng hồ lô, thuẫn và mâu khi bị cưỡng ép thu giữ."],"capNhatToi":"@c1401","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1401","loai":"xuất hiện","importance":"normal","giaiDoan":"Mảnh tàn khuyết lộ diện","text":"Một góc rơi khỏi dao cầu Trảm Tiên đài hóa thành chùm sáng, liên tục xuyên hư không và phá hỏng các binh khí dùng để thu giữ.","anchor":"hẳn là Trảm Tiên đài trên dao cầu đoạn lạc một góc lưu"}]},"nguon":["@c1401"]},{"id":"kim-bi-ho-lo","name":"Kim bì hồ lô","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Ông lão cầm kim bì hồ lô"],"chuSoHuu":[{"ten":"Ông lão cầm kim bì hồ lô","tuChuong":"@c1401","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"trangThai":"Bị xuyên thủng đáy","blurb":"Một hồ lô màu vàng có khả năng thu nạp và đi kèm Ngũ Sắc Thần Quang. Pháp bảo bị dị quang từ dao cầu Trảm Tiên đài xuyên thủng đáy.","detail":"Chủ nhân mở hồ lô để hút chùm sáng đang bỏ chạy, nhưng sức xuyên phá của mục tiêu vượt quá khả năng khống chế. Sau khi đáy bị thủng, hồ lô không còn giữ được công năng thu vật.","uyLuc":"Khi mở ra có Ngũ Sắc Thần Quang hỗ trợ thu nạp mục tiêu.","dacDiem":"Hồ lô có lớp vỏ màu vàng nhưng không chịu nổi sức xuyên phá của dị quang.","congNang":["Thu nạp mục tiêu bằng lực hút kết hợp Ngũ Sắc Thần Quang."],"capNhatToi":"@c1401","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1401","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Thất bại khi thu dị quang","text":"Kim bì hồ lô được mở để thu chùm sáng nhưng bị mục tiêu xuyên thủng đáy, làm mất khả năng thu vật.","anchor":"Hồ lô cực kỳ phi phàm, đi kèm Ngũ Sắc Thần Quang"}]},"nguon":["@c1401"]},{"id":"loi-kiep-dich","name":"Lôi kiếp dịch","cn":"","aliases":[],"category":"khac","categoryLabel":"Thần dịch","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Được chia dùng trong tiểu tụ","blurb":"Chất lỏng óng ánh chứa trong Lôi Trì, được Thạch Hạo gọi là thần tửu.","detail":"Những sinh vật giống Chân Long được nhìn thấy bơi trong lôi kiếp dịch. Thạch Hạo đề nghị mời mọi người uống chất lỏng này và ngồi lại nghiên cứu bí mật của Lôi Trì.","phanLoaiPhu":"Thần dịch","hinhDang":"Chất lỏng óng ánh","chuHienThoi":"Thạch Hạo","congNang":["Có thể được dùng như thần tửu để mời mọi người cùng thưởng thức và nghiên cứu.","Có thể dùng làm linh dịch uống trong tiệc tụ họp."],"dacDiem":"Nằm trong Lôi Trì và là nơi các sinh vật giống Chân Long được nhìn thấy bơi lội.","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1402","denChuong":"","cachCoDuoc":"Được lấy ra từ chiếc đỉnh do Thạch Hạo mang theo.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1402","tabs":{"tienTrinh":[{"chuong":"@c1402","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đề nghị dùng như thần tửu","text":"Thạch Hạo mời mọi người uống lôi kiếp dịch rồi cùng ngồi lại nghiên cứu Lôi Trì.","anchor":"Ta xin mọi người uống một chén thần tửu ---- lôi kiếp dịch"},{"chuong":"@c1410","loai":"dùng","importance":"normal","giaiDoan":"Chia cho các cố nhân","text":"Thạch Hạo lấy lôi kiếp dịch từ trong đỉnh và chia cho các thành viên dự tiểu tụ cùng uống.","anchor":"Thạch Hạo lấy ra con kia đỉnh, ở đây vui lòng phân phát","phamCap":"Không rõ"}]},"nguon":["@c1402","@c1410"]},{"id":"thi-the-muoi-vuong-toc-di-vuc","name":"Thi thể mười Vương tộc Dị Vực","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chiến lợi phẩm","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đã dùng trong yến tiệc","blurb":"Thi thể của mười sinh linh Vương tộc Dị Vực bị Thạch Hạo chém giết tại biên quan Đại Xích Thiên. Chúng được đem ra nướng trong buổi tụ hội tại Đế quan.","detail":"Đây là chiến lợi phẩm từ trận chiến tại biên quan Đại Xích Thiên, mang huyết mạch Vương tộc Dị Vực và được dùng làm thức ăn quý trong yến tiệc.","dacDiem":"Mang huyết mạch Vương tộc Dị Vực cường đại.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1403","denChuong":"@c1403","cachCoDuoc":"Chém giết mười Vương tộc Dị Vực tại biên quan Đại Xích Thiên.","trangThai":"Đã dùng trong yến tiệc"}],"capNhatToi":"@c1403","tabs":{"tienTrinh":[{"chuong":"@c1403","loai":"dùng","importance":"normal","giaiDoan":"Chiến lợi phẩm được dùng mở tiệc","text":"Thạch Hạo đem thi thể mười Vương tộc Dị Vực thu được tại Đại Xích Thiên ra để mọi người nướng làm thức ăn.","anchor":"đây là Hoang huynh tại Đại Xích Thiên biên quan chém giết mười Vương"}]},"nguon":["@c1403"]},{"id":"ban-than-qua","name":"Bán Thần quả","cn":"","aliases":[],"category":"khac","categoryLabel":"Linh quả","phamCap":"","soHuu":["Thác Cổ Ngự Long"],"trangThai":"Được chia trong yến tiệc","blurb":"Linh quả quý do Thác Cổ Ngự Long mang tới cuộc tụ hội tại Đế quan. Hàng chục quả được lấy ra để mọi người cùng thưởng thức.","detail":"Bán Thần quả được dùng làm món ăn quý trong yến tiệc trước ngày các thiên tài ra chiến trường.","chuHienThoi":"Thác Cổ Ngự Long","chuSoHuu":[{"ten":"Thác Cổ Ngự Long","tuChuong":"@c1403","denChuong":"@c1403","cachCoDuoc":"","trangThai":"Đã mang ra chia sẻ"}],"capNhatToi":"@c1403","tabs":{"tienTrinh":[{"chuong":"@c1403","loai":"dùng","importance":"normal","giaiDoan":"Góp vào yến tiệc","text":"Thác Cổ Ngự Long mang hàng chục Bán Thần quả ra mời những người dự tiệc cùng thưởng thức.","anchor":"ta chỗ này có Bán Thần quả mấy chục viên, chư vị nếm thử"}]},"nguon":["@c1403"]},{"id":"than-mang-do-sam-trong-loi-tri","name":"Thần mang đỏ sậm trong Lôi Trì","cn":"","aliases":["Thần mang đỏ sậm trong Lôi Trì"],"category":"khac","categoryLabel":"Thần mang","phamCap":"","soHuu":[],"trangThai":"Bị Mạnh Thiên Chính trấn áp trong Lôi Trì","blurb":"Một chùm sáng đỏ sậm có màu sắc tương đồng với trảm tiên dao cầu và tỏa ra cảm giác đáng sợ. Thạch Hạo cân nhắc dùng nó để rèn luyện thân thể.","detail":"Sau khi bình ổn, thần mang nằm yên trong Lôi Trì. Thạch Hạo nghiêng về phương án dung hợp nó với thân thể thay vì luyện vào binh khí.","phanLoaiPhu":"Thần mang","hinhDang":"Chùm sáng màu đỏ sậm","uyLuc":"Tỏa ra cảm giác đáng sợ.","dacDiem":"Có màu sắc tương đồng với trảm tiên dao cầu.","congNang":["Có thể được dùng để rèn luyện thân thể.","Có thể bạo động và tìm cách thoát khỏi Lôi Trì."],"capNhatToi":"@c1404","tabs":{"tienTrinh":[{"chuong":"@c1404","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nghiên cứu","text":"Thạch Hạo cân nhắc dùng thần mang đỏ sậm để rèn luyện thân thể.","anchor":"Hắn đang suy nghĩ, làm sao lợi dụng này đạo thần mang rèn luyện thân thể"},{"chuong":"@c1410","loai":"dùng","importance":"normal","giaiDoan":"Bạo động khi mở ao","text":"Tia thần mang bạo động và định bỏ chạy sau khi phong ấn Lôi Trì được mở, nhưng bị Mạnh Thiên Chính trấn áp.","anchor":"Hiện tại, nó lại muốn bạo động, muốn bỏ chạy.","phamCap":"Không rõ"}]},"nguon":["@c1404","@c1410"]},{"id":"tien-nguyen","name":"Tiên Nguyên","cn":"","aliases":["Kỳ thạch màu vàng từ dị vực","Tảng đá của Tề Hoành"],"category":"nguyen-lieu","categoryLabel":"Kỳ vật","phamCap":"","soHuu":["Tề Hoành"],"trangThai":"Được Tề Hoành công bố","blurb":"Kỳ thạch màu vàng lấy từ dị vực có thể tự lơ lửng và chứa sinh mệnh tinh khí tinh thuần. Một mảnh nhỏ có thể được hấp thu để hỗ trợ tu luyện.","detail":"Kỳ thạch nhẹ như không, phát thần hà rực rỡ và chứa tinh khí sinh mệnh tinh thuần. Vật này do một vị Chí Tôn ở tổ đàn thu được sau trận huyết chiến ngoài quan ải rồi được Tề Hoành đưa ra tại cuộc tụ hội.","phanLoaiPhu":"Kỳ vật","hinhDang":"Khối đá màu vàng có thể lơ lửng","nguonGoc":"Được thu từ dị vực sau một trận huyết chiến ngoài quan ải.","uyLuc":"Cung cấp sinh mệnh tinh khí tinh thuần để hỗ trợ tu luyện.","dacDiem":"Có thể huyền không, nhẹ như không và phát thần hà rực rỡ.","congNang":["Một mảnh nhỏ có thể được hấp thu trực tiếp vào cơ thể để hỗ trợ tu luyện."],"chuHienThoi":"Tề Hoành","chuSoHuu":[{"ten":"Tề Hoành","tuChuong":"@c1404","denChuong":"","cachCoDuoc":"Được vị Chí Tôn ở tổ đàn giao cho mang tới cuộc tụ hội.","trangThai":"Đang giữ"}],"capNhatToi":"@c1404","tabs":{"tienTrinh":[{"chuong":"@c1404","loai":"xuất hiện","importance":"normal","giaiDoan":"Được công bố","text":"Tề Hoành đưa kỳ thạch ra và trình bày khả năng hỗ trợ tu luyện của nó.","anchor":"Vật này tự nhiên kinh người, bẻ xuống một khối nhỏ, có thể trực tiếp hấp thu tiến vào trong cơ thể"}]},"nguon":["@c1404"]},{"id":"huyet-thanh-mau-vang-nhat","name":"Huyết thanh màu vàng nhạt","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Kỳ vật dạng lỏng","phamCap":"","soHuu":[],"trangThai":"Đã được thu về nghiên cứu","blurb":"Huyết thanh đồng nguyên với Tiên Nguyên chứa vật chất Trường Sinh và có khả năng phong ấn sinh linh. Một con kiến bị niêm phong suốt vạn năm vẫn giữ nguyên sức sống khi lớp đá được cắt mở.","detail":"Chất lỏng màu vàng nhạt có thể đông lại thành đá và được cho là có thể ăn. Công dụng nổi bật của nó là duy trì trạng thái sinh mệnh cực lâu trong khi sinh linh bị phong ấn.","phanLoaiPhu":"Kỳ vật dạng lỏng","hinhDang":"Huyết thanh màu vàng nhạt, có thể đông thành đá","nguonGoc":"Được một vị Chí Tôn ở tổ đàn thu về cùng Tiên Nguyên.","uyLuc":"Có thể phong ấn sinh linh ít nhất vạn năm mà vẫn bảo toàn sức sống.","dacDiem":"Chứa vật chất Trường Sinh và đồng nguyên với Tiên Nguyên.","congNang":["Phong ấn sinh linh và duy trì sức sống qua thời gian cực dài."],"capNhatToi":"@c1404","tabs":{"tienTrinh":[{"chuong":"@c1404","loai":"xuất hiện","importance":"major","giaiDoan":"Công năng được hé lộ","text":"Thí nghiệm với một con kiến chứng minh huyết thanh có thể phong ấn sinh linh suốt vạn năm mà vẫn giữ sức sống.","anchor":"Cho đến quá khứ vạn năm, như trước như vậy, sau đó vị chí tôn kia đem khối đá này đầu cắt ra, con kiến sức sống như trước"}]},"nguon":["@c1404"]},{"id":"tan-do-quan-ngoai","name":"Tàn đồ quan ngoại","cn":"","aliases":["Bản đồ da thú tàn khuyết","Cổ da thú","Cổ da thú đồ"],"category":"khac","categoryLabel":"Bản đồ da thú","phamCap":"","soHuu":["Thác Cổ Ngự Long"],"trangThai":"Do Thác Cổ Ngự Long nắm giữ","blurb":"Tấm bản đồ da thú cổ xưa được đoạt từ người dị vực trên chiến trường. Nó liên quan đến một bí mật và cơ duyên lớn ngoài quan ải.","detail":"Người dị vực từng cầm tàn đồ để tìm kiếm một mục tiêu chưa rõ. Manh mối trên bản đồ khiến Thác Cổ Ngự Long gửi thiệp mời tới vùng cấm cổ xưa trên chín tầng trời và nhận được hồi đáp.","phanLoaiPhu":"Bản đồ","hinhDang":"Tấm da thú rách nát vì thời gian","nguonGoc":"Được đoạt từ người dị vực trên chiến trường.","dacDiem":"Có niên đại xa xưa và liên quan tới một bí mật lớn ngoài quan ải.","congNang":["Chỉ dẫn tới một mục tiêu bí mật ngoài quan ải."],"chuHienThoi":"Thác Cổ Ngự Long","chuSoHuu":[{"ten":"Thác Cổ Ngự Long","tuChuong":"@c1404","denChuong":"","cachCoDuoc":"Đoạt từ người dị vực trên chiến trường.","trangThai":"Đang giữ"}],"capNhatToi":"@c1404","tabs":{"tienTrinh":[{"chuong":"@c1404","loai":"xuất hiện","importance":"normal","giaiDoan":"Được công bố","text":"Thác Cổ Ngự Long đưa tàn đồ ra và tiết lộ nó liên quan đến bí mật cùng cơ duyên lớn ngoài quan ải.","anchor":"đây là ở chiến trường đoạt lại, dị vực người từng nắm này đồ đang tìm kiếm cái gì"}]},"nguon":["@c1404"]},{"id":"than-nguyen","name":"Thần Nguyên","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật chất phong ấn","phamCap":"Do Chí Tôn nhân đạo luyện chế","soHuu":[],"trangThai":"Tồn tại","blurb":"Vật chất do Chí Tôn nhân đạo luyện hóa để phong ấn tu sĩ dưới Độn Nhất. Hiệu quả của nó không đủ để phong ấn Chí Tôn chân chính.","detail":"Thần Nguyên được dùng để phân biệt với Tiên Nguyên. Ngay cả vật chất có công hiệu tương tự do tồn tại cấp Bất Hủ luyện ra cũng không đạt tới khả năng phong ấn Chí Tôn của Tiên Nguyên.","phanLoaiPhu":"Vật chất phong ấn","nguonGoc":"Do Chí Tôn nhân đạo luyện chế","congNang":["Phong ấn tu sĩ dưới Độn Nhất."],"dacDiem":"Không thể phong ấn những Chí Tôn chân chính trong thiên địa.","capNhatToi":"@c1408","tabs":{"tienTrinh":[{"chuong":"@c1408","loai":"xuất hiện","importance":"normal","giaiDoan":"Được giải thích","text":"Ông lão dùng Thần Nguyên để đối chiếu và làm rõ công hiệu vượt trội của Tiên Nguyên.","anchor":"Thần Nguyên, không có cái kia hiệu quả, không làm được, phong ấn không được trong thiên địa chân chính có mấy Chí Tôn"}]},"nguon":["@c1408"]},{"id":"tien-thien-chi-tinh","name":"Tiên thiên chi tinh","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thiên địa bản nguyên tinh hoa","phamCap":"Thiên địa kỳ vật","soHuu":[],"trangThai":"Tồn tại trong thiên nhiên","blurb":"Bản nguyên tinh hoa của thế giới, có thể kết thành tinh bích trong thiên địa. Nó hỗ trợ tu hành và có thể được luyện hóa thành vật liệu phong ấn.","detail":"Nhân vật tuyệt đỉnh có thể luyện hóa tiên thiên chi tinh thành chất lỏng để phong ấn sinh vật, nhưng hiệu quả thông thường không đủ đối với cao thủ chân chính. Tiên Nguyên vốn là tiên thiên chi tinh đã nhiễm lượng lớn Trường Sinh vật chất.","phanLoaiPhu":"Bản nguyên tinh hoa","nguonGoc":"Hình thành trong thiên địa","congNang":["Hỗ trợ tu hành.","Có thể được luyện hóa thành chất lỏng dùng để phong ấn sinh vật."],"dacDiem":"Có thể kết thành tinh bích và là nền tảng hình thành Tiên Nguyên khi nhiễm Trường Sinh vật chất.","capNhatToi":"@c1408","tabs":{"tienTrinh":[{"chuong":"@c1408","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ bản chất","text":"Ông lão giải thích tiên thiên chi tinh là bản nguyên tinh hoa của thế giới và có thể kết thành tinh bích.","anchor":"Tiên thiên chi tinh, là thế giới này bản nguyên tinh hoa, ở trong thiên địa có thể kết thành tinh bích các loại"}]},"nguon":["@c1408"]},{"id":"menh-thach-thai-so-co-quang","name":"Mệnh thạch Thái Sơ cổ quáng","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Kỳ thạch","phamCap":"Loại quý nhất có giá trị vượt Tiên Nguyên","soHuu":[],"trangThai":"Loại quý nhất đã khô cạn","blurb":"Kỳ thạch từng tồn tại trong Thái Sơ cổ quáng. Loại quý báu nhất được đánh giá có giá trị vượt Tiên Nguyên nhưng nay đã khô cạn.","detail":"Ngay cả mệnh thạch thông thường cùng những phần đầu thừa đuôi thẹo còn sót lại cũng có thể trở thành báu vật ở đời sau. Loại mệnh thạch quý nhất đã không còn có thể tìm thấy.","phanLoaiPhu":"Kỳ thạch","nguonGoc":"Thái Sơ cổ quáng","dacDiem":"Loại quý báu nhất có giá trị vượt Tiên Nguyên nhưng đã khô cạn.","capNhatToi":"@c1408","tabs":{"tienTrinh":[{"chuong":"@c1408","loai":"xuất hiện","importance":"normal","giaiDoan":"Được tiết lộ","text":"Ông lão cho biết loại mệnh thạch quý nhất từng có giá trị vượt Tiên Nguyên nhưng nay đã khô cạn.","anchor":"quý báu nhất mệnh thạch muốn so với Tiên Nguyên trả giá trị lớn, thế nhưng bây giờ loại kia mệnh thạch từ lâu khô cạn"}]},"nguon":["@c1408"]},{"id":"loi-tri","name":"Lôi Trì","cn":"","aliases":["Lôi Trì bằng cổ nham thạch"],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã mở phong ấn, tia thần mang bên trong bị trấn áp","blurb":"Ao cổ bằng nham thạch được lão già vùng cấm đặc biệt căn dặn Thạch Hạo phải giữ gìn. Dưới đáy ao có ba sinh linh giống Chân Long đang bơi lội.","detail":"Mạnh Thiên Chính mở phong ấn Lôi Trì, trấn áp tia thần mang định đào thoát và yêu cầu đưa Lôi Linh vào trong ao.","phanLoaiPhu":"Ao cổ chứa lực lượng lôi đạo","hinhDang":"Ao làm từ cổ nham thạch","uyLuc":"Có thể dung chứa sinh linh lôi đạo và tia thần mang phát sinh sau khi dao cầu Trảm Tiên tan rã.","dacDiem":"Nơi sâu nhất dưới đáy ao có ba sinh linh mang hình dáng giống Chân Long.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1410","congNang":["Có thể chứa sinh linh lôi đạo.","Dung chứa ba sinh linh giống Chân Long tại nơi sâu nhất dưới đáy ao."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1410","denChuong":"","cachCoDuoc":"Đang nắm giữ và được khách vùng cấm căn dặn bảo quản.","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1410","loai":"khai phong","importance":"normal","giaiDoan":"Mở phong ấn","text":"Mạnh Thiên Chính mở phong ấn Lôi Trì, trấn áp tia thần mang định đào thoát và quan sát ba sinh linh giống Chân Long dưới đáy ao.","anchor":"có thể nhìn thấy dường như vực sâu nơi sâu xa nhất ba cái sinh linh bơi lội","phamCap":"Không rõ"}]},"nguon":["@c1410"]},{"id":"ba-chan-long-lac-an","name":"Ba Chân Long lạc ấn","cn":"","aliases":[],"category":"khac","categoryLabel":"Ấn ký","phamCap":"Không rõ","soHuu":[],"trangThai":"Nằm trong Lôi Trì","blurb":"Ba lạc ấn dưới đáy Lôi Trì phù hợp với ba Lôi Linh và được nhận định phần lớn do Chân Long lưu lại.","detail":"Các lạc ấn không phải Chân Long ấu thể đang sống. Chúng chứa quy tắc mơ hồ liên quan tới nguồn gốc và sự sáng tạo sinh mệnh, đồng thời có thể đem lại cơ hội tiến hóa theo hướng Chân Long.","phanLoaiPhu":"Lạc ấn Chân Long","nguonGoc":"Phần lớn được nhận định là do Chân Long lưu lại","uyLuc":"Có thể liên quan tới quá trình tạo hóa sinh mệnh và con đường tiến hóa về phía Chân Long.","dacDiem":"Ẩn chứa quy tắc nguồn gốc sự sống và tương ứng với ba Lôi Linh.","congNang":["Chứa quy tắc mơ hồ về nguồn gốc và sự sáng tạo sinh mệnh.","Có thể đem lại cơ hội cho sinh linh tiến hóa theo hướng Chân Long."],"boCha":"loi-tri","dinhDanh":"goc","capNhatToi":"@c1411","tabs":{"tienTrinh":[{"chuong":"@c1411","loai":"xuất hiện","importance":"major","giaiDoan":"Lộ bí mật sinh mệnh","text":"Ba bóng Chân Long được xác nhận là lạc ấn chứa quy tắc mơ hồ về nguồn gốc sự sống.","anchor":"Này ba đạo ấn ký trong dường như ẩn chứa nguồn gốc của sự sống mơ hồ quy tắc."}]},"nguon":["@c1411"]},{"id":"chan-tien-hoat-huyet-cua-cha-vuong-truong-sinh","name":"Chân Tiên hoạt huyết của cha Vương Trường Sinh","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Bảo huyết","phamCap":"Chân Tiên","soHuu":["Vương gia"],"trangThai":"Được phong ấn trong Sinh Mệnh Thủy Tinh","blurb":"Một giọt tinh huyết còn sống được lấy từ cha Vương Trường Sinh khi vị Chân Tiên này ở thời kỳ đỉnh phong.","detail":"Giọt máu đã được luyện sạch sát khí và vật chất gây hại nhưng vẫn duy trì hoạt tính dồi dào như đang lưu chuyển trong cơ thể. Vương gia đưa bảo huyết tới để bồi tội và hỗ trợ Thạch Hạo tăng cường thực lực.","phanLoaiPhu":"Tinh huyết Chân Tiên còn sống","nguonGoc":"Lấy từ cha Vương Trường Sinh khi ông còn sống ở thời kỳ đỉnh phong","vatLieu":"Tinh huyết Chân Tiên","uyLuc":"Bảo lưu hoạt tính của tinh huyết Chân Tiên thời đỉnh phong.","dacDiem":"Đã luyện sạch vật chất có hại và không phải tử huyết.","congNang":["Có thể dùng để hỗ trợ hậu nhân và tăng cường thực lực."],"chuSoHuu":[{"ten":"Vương gia","tuChuong":"@c1411","denChuong":"@c1411","cachCoDuoc":"Lưu giữ tinh huyết của Chân Tiên trong gia tộc","trangThai":"Đã đưa ra bồi tội"}],"dinhDanh":"goc","capNhatToi":"@c1411","tabs":{"tienTrinh":[{"chuong":"@c1411","loai":"đổi chủ","importance":"major","giaiDoan":"Vương gia đưa bảo huyết","text":"Vương gia đưa giọt hoạt huyết Chân Tiên được bảo tồn trong Sinh Mệnh Thủy Tinh tới làm vật bồi tội.","anchor":"Đây là còn sống máu tươi, mà không chết máu!","phamCap":"Chân Tiên"}]},"nguon":["@c1411"]},{"id":"sinh-menh-thuy-tinh","name":"Sinh Mệnh Thủy Tinh","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phong ấn","phamCap":"Không rõ","soHuu":["Vương gia"],"trangThai":"Đang phong ấn Chân Tiên hoạt huyết","blurb":"Khối thủy tinh cỡ nắm tay trẻ con được dùng để phong ấn một giọt Chân Tiên hoạt huyết.","detail":"Sinh Mệnh Thủy Tinh duy trì hoạt tính dồi dào của bảo huyết, giúp giọt máu vẫn biểu hiện như đang lưu chuyển trong cơ thể sống.","hinhDang":"Khối thủy tinh cỡ nắm tay trẻ con","congNang":["Phong ấn và bảo trì hoạt tính của Chân Tiên hoạt huyết."],"dacDiem":"Có khả năng duy trì trạng thái sống của tinh huyết được phong ấn.","dinhDanh":"goc","capNhatToi":"@c1411","tabs":{"tienTrinh":[{"chuong":"@c1411","loai":"xuất hiện","importance":"normal","giaiDoan":"Phong ấn hoạt huyết","text":"Sinh Mệnh Thủy Tinh xuất hiện với vai trò phong ấn và duy trì hoạt tính của giọt Chân Tiên tinh huyết.","anchor":"Bảo trì nhất dồi dào hoạt tính, phong ấn tại Sinh Mệnh Thủy Tinh trong"}]},"nguon":["@c1411"]},{"id":"tien-huyet-song-sot","name":"Tiên huyết sống sót","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Tiên huyết","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Được giữ trong thủy tinh","blurb":"Một giọt Tiên huyết óng ánh có thể trợ giúp Thạch Hạo đột phá và rèn luyện thân thể.","detail":"Thạch Hạo chưa dùng toàn bộ Tiên huyết để tiến vào Trảm Ngã Cảnh vì muốn tới quan ngoại Tiên mài giũa. Khi việc luyện hóa thần mang gặp trở ngại, hắn chỉ dẫn một tia máu từ thủy tinh xuống ngón tay để trợ luyện.","phanLoaiPhu":"Tiên huyết","hinhDang":"Một giọt máu óng ánh được giữ trong thủy tinh","congNang":["Có khả năng trợ giúp Thạch Hạo vượt Hư Đạo Cảnh để tiến vào Trảm Ngã Cảnh.","Một tia Tiên huyết được dùng để rèn ngón tay và hỗ trợ dung hợp thần mang."],"dacDiem":"Tỏa khí tức thần thánh và ánh sáng đỏ sẫm.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1412","denChuong":"","cachCoDuoc":"","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1412","loai":"dùng","importance":"normal","giaiDoan":"Trợ luyện thần mang","text":"Thạch Hạo dẫn một tia Tiên huyết từ thủy tinh xuống ngón tay để hỗ trợ quá trình dung hợp thần mang.","anchor":"Thạch Hạo không có toàn bộ đổ ra, chỉ là để nó từ thủy tinh bên trong chảy ra một tia, rơi vào trên ngón tay của hắn","phamCap":""}]},"capNhatToi":"@c1412","nguon":["@c1412"]},{"id":"chien-tien-dao-cau","name":"Chiến Tiên dao cầu","cn":"","category":"khac","categoryLabel":"Dị vật","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang do Thạch Hạo nắm giữ","blurb":"Một dao cầu có thể tràn ra tinh khí, được Thạch Hạo dẫn thành thần mang đỏ sậm để xuyên cắt đối thủ.","detail":"Một sợi tinh khí từ Chiến Tiên dao cầu dễ dàng cắt đứt đuôi và xuyên thủng thân thể quái vật Trảm Ngã cảnh. Việc vận dụng sức mạnh này khiến tinh khí trong cơ thể Thạch Hạo gần như khô cạn, nên hắn chỉ định dùng nó làm đòn sát thủ khi cần thiết.","phanLoaiPhu":"Dao cầu","uyLuc":"Thần mang tạo từ một sợi tinh khí có thể xuyên thủng cao thủ Trảm Ngã cảnh.","dacDiem":"Sức xuyên cắt rất mạnh nhưng tiêu hao tinh khí của người sử dụng cực lớn.","chuHienThoi":"Thạch Hạo","congNang":["Phóng tinh khí thành thần mang đỏ sậm có khả năng xuyên cắt thân thể đối thủ."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1414","denChuong":"","cachCoDuoc":"Không nêu trong chương","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1414","loai":"dùng","importance":"normal","giaiDoan":"Thử nghiệm tinh khí","text":"Thạch Hạo dẫn một sợi tinh khí từ dao cầu thành thần mang đỏ sậm, cắt đuôi và xuyên thủng quái vật Trảm Ngã cảnh nhưng gần như cạn sạch tinh khí.","anchor":"đây là Chiến Tiên dao cầu tràn ra một đạo tinh khí","phamCap":"Không rõ"}]},"capNhatToi":"@c1414","nguon":["@c1414"]},{"id":"dai-la-kiem-thai","name":"Đại La kiếm thai","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"dang-co","blurb":"Kiếm thai của Thạch Hạo có thể phát huy uy lực mạnh hơn khi chịu áp bức. Nó tỏa ánh sáng chói mắt khi đối đầu sức ép từ tu sĩ Độn Nhất.","detail":"Thạch Hạo lấy Đại La kiếm thai ra khi bàn tay lớn của tu sĩ Độn Nhất chộp xuống. Dưới áp lực mạnh, kiếm thai phát sáng rực rỡ như hiện cảnh Vũ Hóa Phi Tiên, khiến kẻ truy kích nảy ý muốn đoạt lấy.","congNang":["Chịu áp bức càng mạnh thì càng phát huy uy lực lớn hơn."],"uyLuc":"Có thể bộc phát ánh sáng chói mắt dưới sức ép của tu sĩ Độn Nhất.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1419","denChuong":"","cachCoDuoc":"Đã sở hữu trước khi bị truy kích.","trangThai":"dang-co"}],"capNhatToi":"@c1419","tabs":{"tienTrinh":[{"chuong":"@c1419","loai":"dùng","importance":"normal","giaiDoan":"Chống sức ép Độn Nhất","text":"Thạch Hạo lấy Đại La kiếm thai chống lại bàn tay lớn của tu sĩ Độn Nhất, khiến kiếm thai phát sáng và bộc lộ uy lực dưới áp bức.","anchor":"này kiếm thai càng được áp bức phát huy ra uy lực càng lớn"}]},"nguon":["@c1419"]},{"id":"dan-than-duoc-trong-bai-xuong","name":"Đàn Thần dược trong bãi xương","cn":"","category":"dan-duoc","categoryLabel":"Dược vật","phamCap":"Thần dược","soHuu":[],"trangThai":"Ẩn hiện trong bãi xương","blurb":"Một đàn Thần dược nhiều màu xuất hiện giữa khu bãi xương trong Thần Dược Sơn Mạch. Chúng có thể tự chạy trên mặt đất và độn xuống lòng đất.","detail":"Các cây Thần dược mang màu vàng, tím và đỏ rực, tỏa hương thơm cùng sinh cơ mãnh liệt giữa vùng quạnh hiu không có thảo mộc. Chúng tụ thành đàn thay vì xuất hiện riêng lẻ.","phanLoaiPhu":"Thần dược có linh tính","hinhDang":"Dược thảo màu vàng, tím và đỏ rực","dacDiem":"Có thể chạy trên mặt đất, chui xuống đất và tụ thành đàn.","congNang":["Tỏa hương thơm và sinh cơ mãnh liệt."],"capNhatToi":"@c1420","dinhDanh":"goc","nguon":["@c1420"]},{"id":"hoang-dao-tien-kim","name":"Hoàng Đạo Tiên Kim","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Tiên kim","phamCap":"Tiên kim","soHuu":[],"trangThai":"Đã thông linh hóa sinh vật","blurb":"Loại Tiên kim có thể thông linh và hóa thành sinh vật sống. Khối Tiên kim tại Thần Dược Thần Mạch mang hình dạng Hoàng Kim Ngưu.","detail":"Khối Hoàng Đạo Tiên Kim dài hơn một thước đã sinh ra sinh mệnh và sát ý, không phải con rối do người luyện chế. Thân thể của nó cứng rắn, bất hủ và chứa lượng vật liệu đủ lớn để Chân Tiên dùng luyện khí.","phanLoaiPhu":"Tiên kim thông linh","hinhDang":"Hóa thành một con Hoàng Kim Ngưu dài khoảng một thước","dacDiem":"Thông linh hóa thành sinh vật có thân thể Tiên kim bất hủ.","uyLuc":"Thần lực tích lũy lâu đời đủ uy hiếp và chém giết thần linh.","congNang":["Tạo thành thân thể Tiên kim cứng rắn, khó bị bảo thuật làm tổn thương.","Có thể thông linh và hóa thành sinh vật sống."],"tabs":{"tienTrinh":[{"chuong":"@c1421","loai":"khai phong","importance":"major","giaiDoan":"Thông linh hóa sinh","text":"Hoàng Đạo Tiên Kim được phát hiện đã thông linh và hóa thành một con Hoàng Kim Ngưu sống.","phamCap":"Tiên kim","anchor":"nó dĩ nhiên là do Hoàng Đạo Tiên Kim đúc thành, toàn thân vàng óng ánh"}]},"capNhatToi":"@c1421","nguon":["@c1421"]},{"id":"kim-tham-oa-oa","name":"Kim Tham Oa Oa","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dược","phamCap":"Thần dược","soHuu":[],"trangThai":"Tự do trong Thần Dược Thần Mạch","blurb":"Cây thần dược thành tinh mang hình dáng lão sâm màu vàng. Nó có thể di chuyển rất nhanh và tỏa hương thuốc khiến tinh thần sảng khoái.","detail":"Kim Tham Oa Oa có thân hình béo, khuôn mặt già nua đầy râu và toàn thân màu vàng. Khi bị kinh động, nó chạy nhanh giữa nhóm thần dược dưới chân núi.","hinhDang":"Lão sâm màu vàng, béo và có khuôn mặt già nua đầy râu","dacDiem":"Đã thành tinh và có thể tự di chuyển.","congNang":["Hương thuốc giúp người ngửi cảm thấy thư thái và tỉnh táo."],"tabs":{"tienTrinh":[{"chuong":"@c1421","loai":"xuất hiện","importance":"normal","giaiDoan":"Thành tinh","text":"Kim Tham Oa Oa xuất hiện trong quần thể thần dược thành tinh tại Thần Dược Thần Mạch.","phamCap":"Thần dược","anchor":"Một cây lão tham, toàn thân hiện màu vàng, rất béo, cũng rất già nua"}]},"capNhatToi":"@c1421","nguon":["@c1421"]},{"id":"phi-phuong-thao","name":"Phi Phượng Thảo","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dược","phamCap":"Thần dược","soHuu":[],"trangThai":"Tự do trong Thần Dược Thần Mạch","blurb":"Thần dược thành tinh có màu đỏ sẫm như máu và hình dáng tựa Phượng Hoàng giương cánh. Khi di chuyển, nó phát ra mưa sáng thần thánh và dược hương nồng đậm.","detail":"Phi Phượng Thảo chạy giữa vùng núi thần dược với động tác giống như đang múa. Hình thái Phượng Hoàng cùng ánh sáng tỏa ra khiến nó nổi bật trong quần thể thần dược.","hinhDang":"Cỏ đỏ sẫm như máu, hình dáng giống Phượng Hoàng giương cánh","dacDiem":"Đã thành tinh, có thể di chuyển và phát ra mưa sáng thần thánh.","tabs":{"tienTrinh":[{"chuong":"@c1421","loai":"xuất hiện","importance":"normal","giaiDoan":"Thành tinh","text":"Phi Phượng Thảo xuất hiện trong nhóm thần dược sống dưới chân núi.","phamCap":"Thần dược","anchor":"một cây đỏ sẫm như máu Phi Phượng Thảo, dường như giương cánh Phượng Hoàng"}]},"capNhatToi":"@c1421","nguon":["@c1421"]},{"id":"lenh-bai-cua-bat-huu-gia","name":"Lệnh bài của Bất Hủ giả","cn":"","aliases":[],"category":"khac","categoryLabel":"Lệnh bài","phamCap":"Vật thuộc về Bất Hủ giả","soHuu":["Sinh vật hình người đến từ Đế quan"],"trangThai":"Đã được trao cho sinh vật hình người đến từ Đế quan","blurb":"Một thiết bài đen kịt thuộc về Bất Hủ giả, được dùng làm tín vật đi lại trong Dị vực.","detail":"Sinh linh Dị vực tại vùng đất của Bất Hủ giả trao lệnh bài này cho vị khách đến từ Đế quan. Người cầm có thể đi lại trong Dị vực mà không bị ngăn cản.","phanLoaiPhu":"Lệnh bài thông hành","hinhDang":"Thiết bài đen kịt","nguonGoc":"Thuộc về sư phụ là Bất Hủ giả của sinh linh Dị vực","congNang":["Cho phép người cầm đi lại trong Dị vực mà không bị ngăn cản tại @c1422."],"dacDiem":"Vật thuộc về Bất Hủ giả, được trao làm tín vật cho một sinh vật hình người đến từ Đế quan.","chuHienThoi":"Sinh vật hình người đến từ Đế quan","chuSoHuu":[{"ten":"Sinh vật hình người đến từ Đế quan","tuChuong":"@c1422","denChuong":"","cachCoDuoc":"Được sinh linh Dị vực tại vùng đất Bất Hủ giả trao tặng","trangThai":"Đang giữ"}],"capNhatToi":"@c1422","tabs":{"tienTrinh":[{"chuong":"@c1422","loai":"đổi chủ","importance":"major","giaiDoan":"Trao cho vị khách Đế quan","text":"Sinh linh Dị vực trao thiết bài đen kịt của sư phụ cho sinh vật hình người đến từ Đế quan, giúp người này đi lại trong Dị vực mà không bị ngăn cản.","anchor":"xin cầm lấy cái này lệnh bài, cất bước dị vực trung tướng không người cản ngươi"}]},"nguon":["@c1422"]},{"id":"dong-thap-vang-ong","name":"Đồng tháp vàng óng","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo thu giữ","phamCap":"Không rõ","soHuu":["Đại tu sĩ Độn Nhất hộ tống quần địch"],"trangThai":"hong","blurb":"Tòa đồng tháp vàng óng có khả năng bao phủ và thu giữ sinh linh.","detail":"Đại tu sĩ Độn Nhất dùng đồng tháp để thu Hoàng Kim Ngưu, nhưng sinh linh này phá vây khiến cả tòa tháp nổ tung.","congNang":["Bao phủ và thu giữ sinh linh."],"chuHienThoi":"Đại tu sĩ Độn Nhất hộ tống quần địch","chuSoHuu":[{"ten":"Đại tu sĩ Độn Nhất hộ tống quần địch","tuChuong":"@c1424","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Pháp bảo đã bị phá hủy"}],"capNhatToi":"@c1424","tabs":{"tienTrinh":[{"chuong":"@c1424","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị phá hủy","text":"Đồng tháp bao phủ Hoàng Kim Ngưu nhưng bị phá tung từ bên trong.","anchor":"toà này đồng tháp trực tiếp bạo khai, một đoàn hoàng kim quang từ bên trong vọt ra","phamCap":"Không rõ"}]},"nguon":["@c1424"]},{"id":"hoang-dao-thach","name":"Hoàng Đạo thạch","cn":"","aliases":["Hoàng đạo thạch"],"category":"nguyen-lieu","categoryLabel":"Linh thạch","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn số lượng lớn trong địa quật","blurb":"Linh thạch màu vàng nhạt có linh tính mạnh, hiện diện với quy mô lớn trong khu vực dưới lòng đất.","detail":"Hoàng Đạo thạch tỏa ra khí tức thần thánh và tường hòa, có khả năng bao bọc và thai nghén Hoàng Đạo Tiên kim. Số lượng khổng lồ trong hang khiến Thạch Hạo nghi ngờ nơi đây còn tiên kim hoặc một sinh linh khác đang được thai nghén.","phanLoaiPhu":"Linh thạch thai nghén tiên kim","hinhDang":"Nham bích màu vàng nhạt","dacDiem":"Có linh tính mạnh và tạo thành phần lớn nham bích dưới lòng đất.","congNang":["Bao bọc và thai nghén Hoàng Đạo Tiên kim.","Tỏa sương vàng ngưng tụ thành Tiên trấp ngọc dịch.","Có khả năng thai nghén Hoàng Đạo Tiên Kim theo suy đoán của Thạch Hạo."],"capNhatToi":"@c1425","tabs":{"tienTrinh":[{"chuong":"@c1425","loai":"xuất hiện","importance":"normal","giaiDoan":"Phát hiện trong hang ổ","text":"Thạch Hạo nhận ra toàn bộ khu vực dưới lòng đất được tạo thành từ Hoàng Đạo thạch và suy đoán nơi đây còn đang thai nghén tiên kim hoặc sinh linh khác.","anchor":"Chỉnh phiến trong lòng đất đều là Hoàng Đạo thạch, dựng dục Tiên kim thật chỉ có dài hơn một xích sao","phamCap":"Không rõ"},{"chuong":"@c1427","loai":"xuất hiện","importance":"normal","giaiDoan":"Phát hiện công dụng","text":"Thạch Hạo phát hiện lượng lớn Hoàng Đạo thạch tỏa sương vàng tạo thành Tiên trấp ngọc dịch và nghi chúng có thể thai nghén sinh vật Tiên kim.","anchor":"nhiều như vậy hoàng đạo thạch xác thực có thể dựng dục ra lượng lớn Tiên kim mới đúng"}]},"nguon":["@c1425","@c1427"]},{"id":"hoang-kim-ao","name":"Hoàng Kim ao","cn":"","aliases":["Ao vàng"],"category":"khac","categoryLabel":"Ao tiên dịch","phamCap":"Không rõ","soHuu":["Hoàng Kim Ngưu"],"trangThai":"Đang tồn tại","blurb":"Một ao vàng chứa chất lỏng màu vàng lưu chuyển, nằm tại nơi nghỉ chân của Hoàng Kim Ngưu.","detail":"Hoàng Kim ao phóng ra Tiên gia tinh khí cực kỳ nồng đậm. Công dụng cụ thể của chất lỏng trong ao chưa được xác định.","hinhDang":"Ao nhỏ chứa chất lỏng màu vàng","dacDiem":"Tỏa ra Tiên gia tinh khí vô cùng nồng đậm.","chuHienThoi":"Hoàng Kim Ngưu","chuSoHuu":[{"ten":"Hoàng Kim Ngưu","tuChuong":"@c1425","denChuong":"","cachCoDuoc":"Dùng làm nơi nghỉ chân trong hang ổ","trangThai":"Hiện thời"}],"capNhatToi":"@c1425","tabs":{"tienTrinh":[{"chuong":"@c1425","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Thạch Hạo phát hiện","text":"Thạch Hạo tìm thấy Hoàng Kim ao trong ổ nhỏ của Kim Ngưu và cảm nhận Tiên gia tinh khí nồng đậm phả ra từ chất lỏng màu vàng.","anchor":"đó là một cái Hoàng Kim ao, kim sắc nước dịch lưu chuyển","phamCap":"Không rõ"},{"chuong":"@c1427","loai":"dùng","importance":"normal","giaiDoan":"Hỗ trợ hoàn thiện thủy khí","text":"Thạch Hạo ngồi trong ao vàng, luyện hóa chất lỏng và hấp thu bí lực để thủy khí hoàn toàn thành hình.","anchor":"hắn sờ sờ trong ao hoa văn, sau đó lần thứ hai bắt đầu luyện hóa, điên cuồng hấp thu chất lỏng bên trong bí lực."}]},"nguon":["@c1425","@c1427"],"congNang":["Cung cấp bí lực giúp thủy khí hoàn toàn thành hình.","Có khả năng thai nghén hoặc hỗ trợ niết bàn sinh vật Tiên Đạo theo suy đoán của Thạch Hạo."]},{"id":"tien-trap-kim-dich","name":"Tiên trấp Kim dịch","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thiên tài địa bảo dạng dịch","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn tiếp tục trào lên từ sâu dưới lòng đất","blurb":"Chất dịch vàng chứa sinh mệnh năng và khí tức Tiên đạo cực kỳ nồng đậm. Nó nuôi dưỡng nhục thân, thần hồn, trung hòa tổn hại do bản nguyên trọng thương và kích thích Tiên khí trong cơ thể Thạch Hạo.","detail":"Tiên trấp Kim dịch tụ trong một ao nhỏ giữa Hoàng Đạo Thạch nhưng nguồn chân chính nằm sâu hơn dưới lòng đất. Kim dịch không chữa được vết thương đại đạo từ căn nguyên, song có thể nuôi dưỡng thân thể và thần hồn, xóa bớt phần tổn hại đang ăn mòn Thạch Hạo. Khí tức Tiên đạo của nó còn khiến ba đạo Tiên khí tụ tán và thúc đẩy thủy khí từng biến mất tái hiện.","phanLoaiPhu":"Dịch thể Tiên đạo","hinhDang":"Chất dịch màu vàng","nguonGoc":"Trào lên qua các khe nhỏ từ không gian sâu dưới đáy ao Hoàng Đạo Thạch.","uyLuc":"Có thể nuôi dưỡng nhục thân và thần hồn, đồng thời kích thích Tiên khí.","dacDiem":"Chứa sinh mệnh năng và khí tức Tiên đạo nồng đậm.","capNhatToi":"@c1426","congNang":["Nuôi dưỡng nhục thân và thần hồn.","Trung hòa phần tổn hại do bản nguyên trọng thương gây ra.","Kích thích ba đạo Tiên khí tụ tán.","Cung cấp bí lực khiến thủy khí của Thạch Hạo tái hiện."],"tabs":{"tienTrinh":[{"chuong":"@c1426","loai":"xuất hiện","importance":"major","giaiDoan":"Phát hiện trong ao đá","text":"Thạch Hạo phát hiện và hấp thu Tiên trấp Kim dịch để áp chế tổn hại nhục thân cùng thần hồn, đồng thời nhận ra nguồn dịch còn nằm sâu dưới lòng đất.","anchor":"bên trong uẩn Tiên Đạo khí tức không ngừng bị lấy ra","phamCap":"Không rõ"}]},"nguon":["@c1426"]},{"id":"tien-trap-ngoc-dich","name":"Tiên trấp ngọc dịch","cn":"","aliases":[],"category":"khac","categoryLabel":"Nước quý","phamCap":"Tiên liệu chưa rõ phẩm cấp","soHuu":["Thạch Hạo"],"trangThai":"Được hấp thu để tu luyện","blurb":"Chất lỏng quý hình thành từ sương vàng bốc lên trong Hoàng đạo thạch. Thạch Hạo hấp thu nó để nuôi dưỡng thủy khí.","detail":"Tiên trấp ngọc dịch ngưng tụ từ từng sợi sương vàng trong địa quật. Thạch Hạo suy đoán chất lỏng này còn có khả năng thai nghén hoặc hỗ trợ phục sinh sinh vật Tiên Đạo.","phanLoaiPhu":"Dịch thể từ Hoàng đạo thạch","nguonGoc":"Sương vàng bốc lên từ Hoàng đạo thạch ngưng tụ thành chất lỏng.","hinhDang":"Chất lỏng do sương vàng ngưng tụ","uyLuc":"Cung cấp bí lực giúp thủy khí của Thạch Hạo hoàn toàn thành hình.","dacDiem":"Được nghi có khả năng thai nghén hoặc phục sinh sinh vật Tiên Đạo.","congNang":["Nuôi dưỡng thủy khí trong Luân Hải của Thạch Hạo.","Có khả năng thai nghén sinh vật Tiên Đạo theo suy đoán của Thạch Hạo."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1427","denChuong":"","cachCoDuoc":"Hấp thu từ ao vàng","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1427","tabs":{"tienTrinh":[{"chuong":"@c1427","loai":"dùng","importance":"normal","giaiDoan":"Hấp thu nuôi thủy khí","text":"Thạch Hạo hấp thu Tiên trấp ngọc dịch trong ao vàng để cung cấp bí lực cho thủy khí.","anchor":"phát hiện hết thảy Tiên trấp ngọc dịch đều là từ hoàng đạo trong đá bốc hơi lên từng tia từng sợi màu vàng mịt mờ sương mù hóa thành chất lỏng."}]},"nguon":["@c1427"]},{"id":"chan-long-nghich-lan","name":"Chân Long nghịch lân","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo nắm giữ","blurb":"Lân phiến Chân Long được Thạch Hạo dùng để che chắn Thần thức khi dò xét màn sáng kim quang.","detail":"Chân Long nghịch lân không chống đỡ được lực lượng của màn sáng, bị đánh bật và khiến Thạch Hạo chịu chấn động ở mi tâm.","congNang":["Che chắn Thần thức khi tiếp cận lực lượng có thể tổn thương Nguyên Thần. @c1428"],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1428","denChuong":"","cachCoDuoc":"","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1428","tabs":{"tienTrinh":[{"chuong":"@c1428","loai":"dùng","importance":"normal","giaiDoan":"Che chắn Thần thức","text":"Thạch Hạo dùng Chân Long nghịch lân ngăn màn sáng kim quang nhưng lân phiến bị đánh bật.","anchor":"Chân Long nghịch lân run rẩy, Thạch Hạo như bị sét đánh"}]},"nguon":["@c1428"]},{"id":"chien-xa-hoang-dao-tien-kim","name":"Chiến xa Hoàng Đạo Tiên Kim","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến xa","phamCap":"Không rõ","soHuu":[],"trangThai":"Vỡ thành hai phần","blurb":"Chiến xa cổ nhỏ được tế luyện hoàn toàn từ Hoàng Đạo Tiên Kim, hiện đã vỡ nát trong mật địa dưới ao vàng.","detail":"Chiến xa chỉ dài khoảng một thước, mất nửa buồng xe và nằm cạnh tàn thể Kim Ngưu. Trong phần buồng còn lại có một lão đạo nhân tóc vàng râu vàng ngồi xếp bằng.","phanLoaiPhu":"Tọa giá","hinhDang":"Chiến xa nhỏ dài khoảng một thước, vỡ thành hai phần và mất nửa buồng xe.","vatLieu":"Hoàng Đạo Tiên Kim","dacDiem":"Toàn bộ chiến xa được tế luyện từ Hoàng Đạo Tiên Kim.","capNhatToi":"@c1428","tabs":{"tienTrinh":[{"chuong":"@c1428","loai":"xuất hiện","importance":"normal","giaiDoan":"Chiến xa vỡ nát","text":"Thạch Hạo phát hiện chiến xa cổ vỡ nát được tế luyện hoàn toàn từ Hoàng Đạo Tiên Kim.","anchor":"thế nhưng cầm Tiên kim tới tế luyện thành chiến xa cũng quá xa xỉ"}]},"nguon":["@c1428"]},{"id":"tan-the-kim-nguu-hoang-dao-tien-kim","name":"Tàn thể Kim Ngưu Hoàng Đạo Tiên Kim","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Tàn thể sinh linh","phamCap":"Không rõ","soHuu":[],"trangThai":"Chia năm xẻ bảy","blurb":"Tàn thể Kim Ngưu cấu thành từ Hoàng Đạo Tiên Kim nằm cạnh chiến xa cổ trong mật địa.","detail":"Đầu, sừng và tứ chi đã lìa khỏi thân. Những lỗ tên, vết rìu và đao ấn trên tàn thể còn lưu đạo vận thuộc lĩnh vực Tiên đạo.","vatLieu":"Hoàng Đạo Tiên Kim","dacDiem":"Thương tích trên tàn thể chứa đạo vận Tiên đạo và được Đoàn Tiên Hỏa soi rọi, sao chép.","capNhatToi":"@c1428","tabs":{"tienTrinh":[{"chuong":"@c1428","loai":"xuất hiện","importance":"normal","giaiDoan":"Tàn thể mang Tiên uẩn","text":"Tàn thể Kim Ngưu được phát hiện bên chiến xa với nhiều thương tích lưu giữ đạo vận Tiên đạo.","anchor":"Đây cũng là Hoàng Đạo Tiên Kim chất liệu, là vô thượng thiên tài địa bảo"}]},"nguon":["@c1428"]},{"id":"dao-bao-hoang-dao-tien-kim","name":"Đạo bào Hoàng Đạo Tiên Kim","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Đạo bào","phamCap":"Không rõ","soHuu":["Lão đạo nhân tóc vàng râu vàng"],"trangThai":"Rách nát","blurb":"Đạo bào vàng trên người lão đạo nhân trong chiến xa được bện từ Hoàng Đạo Tiên Kim.","detail":"Bộ đạo bào đã rách nát nhưng không mục rữa như quần áo thông thường vì chất liệu cấu thành là Hoàng Đạo Tiên Kim.","phanLoaiPhu":"Đạo bào","hinhDang":"Đạo bào màu vàng đã rách nát.","vatLieu":"Hoàng Đạo Tiên Kim","chuHienThoi":"Lão đạo nhân tóc vàng râu vàng","chuSoHuu":[{"ten":"Lão đạo nhân tóc vàng râu vàng","tuChuong":"@c1428","denChuong":"","cachCoDuoc":"","trangThai":"Đang mặc"}],"dacDiem":"Được bện từ Hoàng Đạo Tiên Kim nên không mục nát như y phục thông thường.","capNhatToi":"@c1428","tabs":{"tienTrinh":[{"chuong":"@c1428","loai":"xuất hiện","importance":"normal","giaiDoan":"Đạo bào trên lão đạo nhân","text":"Thạch Hạo nhận ra đạo bào rách nát trên người lão đạo nhân được bện từ Hoàng Đạo Tiên Kim.","anchor":"bởi vì quần áo là Hoàng Đạo Tiên Kim bện"}]},"nguon":["@c1428"]},{"id":"than-bi-co-tri","name":"Thần bí cổ trì","aliases":["Kim sắc trì"],"cn":"","category":"khac","categoryLabel":"Bảo trì","phamCap":"Mang thủ đoạn Tiên gia","soHuu":[],"trangThai":"Đang được Thạch Hạo sử dụng để tu luyện","blurb":"Một bảo trì màu vàng chứa tinh hoa có thể rèn giũa thân thể và tẩm bổ Tiên khí. Thạch Hạo nghi ngờ nơi này vốn được chuẩn bị để Hoàng Kim Ngưu niết bàn sống lại.","detail":"Tinh hoa trong trì gột rửa xương cốt, huyết nhục và các môn trong cơ thể Thạch Hạo, giúp Thủy khí ổn định và ba đạo Tiên khí lớn mạnh. Nhờ tác động của trì, đạo Tiên khí thứ hai đủ sức làm Đại đạo chi hoa nở rộ và thai nghén đệ nhị sinh linh, nhưng bản nguyên thương của Thạch Hạo chỉ chuyển biến tốt đôi chút.","phanLoaiPhu":"Bảo trì","dacDiem":"Mang thủ đoạn Tiên gia và chứa sinh khí có thể dẫn phát những biến đổi gần với niết bàn.","uyLuc":"Có thể hỗ trợ Đại đạo chi hoa nở rộ và thai nghén sinh linh từ đạo hạnh cùng sức chiến đấu của Thạch Hạo.","congNang":["Gột rửa xương cốt, huyết nhục và các môn trong cơ thể Thạch Hạo.","Ổn định Thủy khí và tẩm bổ ba đạo Tiên khí.","Hỗ trợ đạo Tiên khí thứ hai nở hoa, thai nghén đệ nhị sinh linh.","Cung cấp sinh khí khiến vạn linh do cốt văn hóa thành xuất hiện hơi thở sự sống."],"capNhatToi":"@c1429","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1429","loai":"dùng","importance":"normal","giaiDoan":"Tẩm bổ đạo cơ","text":"Thần bí cổ trì rèn giũa thân thể Thạch Hạo, củng cố ba đạo Tiên khí và hỗ trợ đóa Đại đạo chi hoa thứ hai thai nghén sinh linh.","anchor":"Lần này, hắn có thể thôi thúc ra Đại đạo chi hoa tỏa ra, đản sinh ra thứ hai sinh linh, cùng cái này kim sắc trì có tuyệt đại quan hệ!"}]},"nguon":["@c1429"]},{"id":"thuy-khi","name":"Thủy khí","aliases":[],"cn":"","category":"khac","categoryLabel":"Khí thần bí","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang phong bế đệ nhị sinh linh","blurb":"Một luồng khí thần bí có quan hệ mật thiết với ba đạo Tiên khí của Thạch Hạo. Nó tự hóa thành Chân Long rồi biến thành hoa văn gông xiềng để phong bế đệ nhị sinh linh.","detail":"Thủy khí dựng lên từ Luân Hải, đi dọc xương sống, xuyên qua linh đài và thoát khỏi thiên linh cái trước khi hóa thành Chân Long xông vào đóa Đại đạo chi hoa thứ hai. Nó chịu được sự chém kích của cánh hoa, trói chặt tiểu nhân mới thành hình rồi hóa thành hoa văn khắc trên người sinh linh này, ngăn cách sinh linh với ngoại giới. Thạch Hạo nhận định nó khó khống chế và có thể phản phệ chủ thể, nhưng vẫn muốn phân giải rồi dung hợp nó vào chân thân.","hinhDang":"Hóa thành hình Chân Long khi xông vào Đại đạo chi hoa, sau đó biến thành hoa văn gông xiềng.","dacDiem":"Khó khống chế, có nguy cơ phản phệ chủ thể và giữ quan hệ một sinh ba với ba đạo Tiên khí.","uyLuc":"Chịu được sự chém kích của cánh Đại đạo chi hoa và phong bế hoàn toàn đệ nhị sinh linh.","congNang":["Có quan hệ sinh thành và ràng buộc với ba đạo Tiên khí.","Hóa thành Chân Long để xông vào Đại đạo chi hoa.","Biến thành hoa văn gông xiềng, phong bế đệ nhị sinh linh với ngoại giới.","Phong bế và trấn áp đệ nhị sinh linh của Thạch Hạo.","Có thể hợp nhất với đệ nhị sinh linh để ngăn Thạch Hạo tiếp tục công kích."],"capNhatToi":"@c1429","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1429","loai":"dùng","importance":"normal","giaiDoan":"Phong ấn sinh linh","text":"Thủy khí rời thân thể Thạch Hạo, hóa thành Chân Long vượt qua cánh hoa rồi biến thành hoa văn gông xiềng phong bế đệ nhị sinh linh.","anchor":"Thủy khí quá mạnh, cầm cố tiểu nhân, càng thu càng chặt, giống như một cái Man Long, quấn quanh ở tiểu nhân trên người, cuối cùng trở thành hoa văn, khắc vào trên."},{"chuong":"@c1430","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp đệ nhị sinh linh","text":"Thủy khí tiếp tục phong bế đệ nhị sinh linh, né tránh Đại La Tiên Kiếm và chỉ bị tinh túy Trảm Tiên Trát Đao lay động.","anchor":"nó nhu lúc Nhược Thủy, cứng rắn lúc càng hơn Tiên kim"}]},"nguon":["@c1429","@c1430"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1430","denChuong":"","cachCoDuoc":"Được thu hồi và tái dưỡng trong thần bí cổ trì","trangThai":"Chưa thể luyện hóa"}]},{"id":"dai-la-tien-kiem","name":"Đại La Tiên Kiếm","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Tiên kiếm","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang được sở hữu","blurb":"Tiên kiếm của Thạch Hạo có thể thu nhỏ và đưa vào trong cơ thể.","detail":"Thạch Hạo thu nhỏ Đại La Tiên Kiếm còn một tấc rồi đưa vào cơ thể để chém Thủy khí. Lưỡi kiếm xuyên qua trạng thái sương mù của Thủy khí nhưng không gây ra tổn thương.","phanLoaiPhu":"Tiên kiếm","hinhDang":"Có thể thu nhỏ còn một tấc.","chuHienThoi":"Thạch Hạo","congNang":["Có thể thu nhỏ và thu vào trong cơ thể.","Được dùng để công kích Thủy khí nhưng không thể làm nó tổn thương."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1430","denChuong":"","cachCoDuoc":"","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1430","tabs":{"tienTrinh":[{"chuong":"@c1430","loai":"dùng","importance":"normal","giaiDoan":"Thử chém Thủy khí","text":"Thạch Hạo thu nhỏ Đại La Tiên Kiếm và đưa vào cơ thể để chém Thủy khí nhưng không thể gây tổn thương cho nó.","anchor":"Thạch Hạo lấy ra Đại La Tiên Kiếm, đem thu vào trong cơ thể"}]},"nguon":["@c1430"]},{"id":"ngoc-thach-thu","name":"Ngọc thạch thư","cn":"","aliases":[],"category":"khac","categoryLabel":"Kinh thư","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Kinh thư chứa kinh văn thuộc hệ thống Tiên Cổ.","detail":"Khi Thạch Hạo đọc thầm ngọc thạch thư, chữ viết cổ xưa hiện lên trong tâm hải rồi hóa thành hoa văn phủ trên thân thể hắn, hỗ trợ quá trình tu luyện Tiên Cổ pháp.","phanLoaiPhu":"Kinh thư Tiên đạo","chuHienThoi":"Thạch Hạo","congNang":["Truyền tải kinh văn Tiên đạo thuộc hệ thống Tiên Cổ."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1430","denChuong":"","cachCoDuoc":"","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1430","tabs":{"tienTrinh":[{"chuong":"@c1430","loai":"dùng","importance":"normal","giaiDoan":"Đọc kinh văn Tiên đạo","text":"Thạch Hạo dùng ngọc thạch thư đọc kinh văn Tiên đạo để tu luyện theo Tiên Cổ pháp.","anchor":"Hắn lấy ra ngọc thạch thư, đọc thầm kinh văn"}]},"nguon":["@c1430"]},{"id":"bi-chat-trong-than-bi-co-tri","name":"Bí chất trong thần bí cổ trì","cn":"","aliases":[],"category":"khac","categoryLabel":"Bảo dịch","phamCap":"","soHuu":[],"trangThai":"Đang được Thạch Hạo hấp thu","blurb":"Bảo dịch hiếm có trong thần bí cổ trì, có khả năng phục sinh sinh linh và bồi dưỡng Tiên khí.","detail":"Bí chất từng giúp Hoàng Kim Ngưu phục sinh và tái dưỡng Thủy khí. Khi được Thạch Hạo hấp thu, nó bồi bổ thân thể, thần hồn và ba đạo Tiên khí, rút ngắn nhiều năm khổ tu cần thiết cho quá trình Tiên khí cắm rễ.","phanLoaiPhu":"Bảo dịch","nguonGoc":"Thần bí cổ trì","dacDiem":"Mỗi giọt đều là bảo dịch hiếm có ở nhân gian.","congNang":["Có thể phục sinh sinh linh.","Có thể tái dưỡng Thủy khí.","Bồi dưỡng thân thể, thần hồn và ba đạo Tiên khí.","Thúc đẩy Tiên khí cắm rễ toàn diện trong thể phách."],"capNhatToi":"@c1430","tabs":{"tienTrinh":[{"chuong":"@c1430","loai":"dùng","importance":"normal","giaiDoan":"Bồi dưỡng Tiên khí","text":"Bí chất trong cổ trì được Thạch Hạo hấp thu để bồi dưỡng ba đạo Tiên khí và thúc đẩy chúng cắm rễ toàn thân.","anchor":"Vì vậy, nó liền Tiên khí đều có thể tẩm bổ"}]},"nguon":["@c1430"]},{"id":"than-the-dai-duoc-tu-cot-tuy-cua-thach-hao","name":"Thân thể đại dược từ cốt tủy của Thạch Hạo","cn":"","category":"dan-duoc","categoryLabel":"Nội dược","phamCap":"Vượt quá cảnh giới hiện tại của Thạch Hạo","soHuu":["Thạch Hạo"],"trangThai":"Đã chín muồi và phụng dưỡng thân thể","blurb":"Nội dược được Thạch Hạo luyện từ cốt tủy của chính mình trong hơn hai trăm bạch cốt thần lô.","detail":"Sau khi chín muồi, thân thể đại dược phụng dưỡng ngược lại cơ thể Thạch Hạo, đẩy toàn bộ cựu huyết ra ngoài và thúc đẩy bách cốt sinh ra thần huyết mới.","phanLoaiPhu":"Đại dược tự thân","nguonGoc":"Được luyện từ cốt tủy của Thạch Hạo.","dacDiem":"Được tạo thành trong các bạch cốt thần lô và tương hợp trực tiếp với cơ thể người luyện.","uyLuc":"Có thể đào thải cựu huyết, thúc đẩy thần huyết tái sinh và phụng dưỡng thân thể.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1431","congNang":["Phụng dưỡng thân thể sau khi chín muồi.","Đào thải cựu huyết và thúc đẩy bách cốt sinh ra thần huyết mới."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1431","denChuong":"","cachCoDuoc":"Tự luyện từ cốt tủy trong quá trình Đại niết bàn.","trangThai":"Đã dùng để phụng dưỡng thân thể"}],"tabs":{"tienTrinh":[{"chuong":"@c1431","loai":"dùng","importance":"normal","giaiDoan":"Chín muồi và phụng dưỡng","phamCap":"Vượt quá cảnh giới hiện tại của Thạch Hạo","text":"Thân thể đại dược chín muồi, phụng dưỡng cơ thể Thạch Hạo, đào thải cựu huyết và thúc đẩy thần huyết tái sinh.","anchor":"Thân thể đại dược thành thục, sắp sửa bắt đầu phụng dưỡng tự thân"}]},"nguon":["@c1431"]},{"id":"bi-bao-nham-vao-kim-nguu","name":"Bí bảo nhằm vào Kim Ngưu","cn":"","category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"Không rõ","soHuu":["Cao thủ dị vực"],"trangThai":"Được mang vào Thần Dược sơn mạch","blurb":"Bí bảo chưa rõ tên được các Đại tu sĩ dị vực mang vào Thần Dược sơn mạch để đối phó Kim Ngưu.","detail":"Sau khi nhận tin đội ngũ dị vực chịu thương vong, các cao thủ mới mang bí bảo này vào núi với mục tiêu kiềm chế Kim Ngưu và hỗ trợ săn giết Thạch Hạo. Hình dạng, phẩm cấp và cơ chế cụ thể chưa được hé lộ.","chuHienThoi":"Cao thủ dị vực","capNhatToi":"@c1431","congNang":["Được chuẩn bị nhằm đối phó Kim Ngưu trong cuộc săn Thạch Hạo."],"chuSoHuu":[{"ten":"Cao thủ dị vực","tuChuong":"@c1431","denChuong":"","cachCoDuoc":"Mang theo trong đợt tăng viện vào Thần Dược sơn mạch.","trangThai":"Đang mang theo"}],"tabs":{"tienTrinh":[{"chuong":"@c1431","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đưa vào sơn mạch","phamCap":"Không rõ","text":"Các cao thủ dị vực mang bí bảo vào Thần Dược sơn mạch nhằm đối phó Kim Ngưu và săn Thạch Hạo.","anchor":"đồng thời lần này mang tới bí bảo, muốn nhằm vào Kim Ngưu, săn bắn Thạch Hạo"}]},"nguon":["@c1431"]},{"id":"ao-chat-long-mau-vang","name":"Ao chất lỏng màu vàng","cn":"","aliases":[],"category":"khac","categoryLabel":"Bảo trì","phamCap":"Chưa xác định","soHuu":[],"trangThai":"Bị đại tu sĩ Độn Nhất dị vực chiếm giữ","blurb":"Một bảo trì chứa chất lỏng màu vàng và thần bí vật chất dưới lòng đất Thần Dược sơn mạch.","detail":"Thần bí vật chất trong ao hỗ trợ quá trình Đại niết bàn của Thạch Hạo, làm vết rách bản nguyên nhạt đi và thúc đẩy chí tôn huyết thức tỉnh, tiến hóa. Đại tu sĩ Độn Nhất dị vực về sau tìm thấy ao, dùng nơi này chữa thương và tin rằng cơ duyên có thể giúp mình trở thành Chí Tôn.","phanLoaiPhu":"Bảo trì","nguonGoc":"Do một tồn tại vô thượng tạo dựng","dacDiem":"Chứa chất lỏng màu vàng có thần bí vật chất hỗ trợ niết bàn.","chuHienThoi":"Đại tu sĩ Độn Nhất dị vực","congNang":["Hỗ trợ Đại niết bàn và phục hồi vết rách bản nguyên.","Kích thích chí tôn huyết của Thạch Hạo thức tỉnh và tiến hóa.","Giúp cường hóa khí huyết và thể phách."],"chuSoHuu":[{"ten":"Đại tu sĩ Độn Nhất dị vực","tuChuong":"@c1432","denChuong":"","cachCoDuoc":"Tìm thấy địa quật sau khi bị Kim Ngưu truy sát","trangThai":"Đang chiếm giữ"}],"capNhatToi":"@c1432","tabs":{"tienTrinh":[{"chuong":"@c1432","loai":"đổi chủ","importance":"major","giaiDoan":"Bị chiếm giữ","text":"Ao vàng thúc đẩy chí tôn huyết của Thạch Hạo tiến hóa trước khi bị đại tu sĩ Độn Nhất dị vực phát hiện và chiếm giữ.","anchor":"hấp thu màu vàng ao bên trong thần bí vật chất, để chí tôn huyết đột nhiên thức tỉnh","phamCap":"Chưa xác định"}]},"nguon":["@c1432"]},{"id":"bach-ho-dang","name":"Bạch Hổ đằng","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dược","phanLoaiPhu":"Thần dược nhiễm tà khí","phamCap":"Thần dược","soHuu":[],"trangThai":"Nhiễm U Minh Chi Lực","blurb":"Một cây thần dược trắng như tuyết, có lá mang hình hổ và khả năng độn thổ cực nhanh. Cây thuốc đã nhiễm tử khí, khiến thần tính nghịch chuyển và trở nên cực kỳ nguy hiểm.","detail":"Bạch Hổ đằng xuất hiện trong Thần Dược sơn mạch và bị tu sĩ dị vực dùng lưới sao truy bắt. Thạch Hạo dùng Thiên Nhãn nhận ra tử khí quấn quanh nó nên không tham gia tranh đoạt; ghi chép hắn từng đọc cho biết thần dược nhiễm U Minh Chi Lực có thể khiến cả Chí Tôn tử vong nếu ăn nhầm.","hinhDang":"Toàn thân trắng như tuyết, lá giống hình hổ.","dacDiem":"Nhiễm tử khí, thần tính nghịch chuyển và chứa U Minh Chi Lực.","uyLuc":"Có thể gây tử vong ngay cả với Chí Tôn nếu bị ăn nhầm.","congNang":["Có thể độn thổ và dịch chuyển cực nhanh trong lòng đất."],"capNhatToi":"@c1433","tabs":{"tienTrinh":[{"chuong":"@c1433","loai":"xuất hiện","importance":"normal","giaiDoan":"Nhiễm U Minh Chi Lực","text":"Bạch Hổ đằng bị các tu sĩ dị vực truy bắt nhưng được Thạch Hạo nhận ra là đã nhiễm yêu tà khí.","anchor":"có chút thần dược không biết bởi vì cớ gì, nhiễm phải yêu tà khí, thần tính nghịch chuyển, nội hàm U Minh Chi Lực","phamCap":"Thần dược"}]},"nguon":["@c1433"]},{"id":"luoi-lon-luyen-tu-ngoi-sao-sa","name":"Lưới lớn luyện từ ngôi sao sa","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phanLoaiPhu":"Lưới bắt giữ","phamCap":"Không rõ","soHuu":["Nhóm tu sĩ dị vực truy bắt Bạch Hổ đằng"],"trangThai":"Không rõ","blurb":"Một tấm lưới lớn được luyện chế từ ngôi sao sa, do nhóm tu sĩ dị vực sử dụng để bắt Bạch Hổ đằng. Nó có thể xuyên sâu vào địa tầng và phá sập vách núi.","detail":"Tấm lưới được ném ra bao phủ khu vực Bạch Hổ đằng bỏ trốn rồi xuyên vào lòng đất của Thần Dược sơn mạch. Trong quá trình truy bắt, nó vô tình kéo lên nhiều xương khô và một quan tài đồng chứa táng sĩ cánh mục nát.","vatLieu":"Ngôi sao sa","uyLuc":"Có thể phá sập vách núi và xuyên qua địa tầng kiên cố.","congNang":["Bao phủ tứ phương để bắt giữ mục tiêu.","Xuyên sâu vào địa tầng trong quá trình truy đuổi."],"chuHienThoi":"Nhóm tu sĩ dị vực truy bắt Bạch Hổ đằng","chuSoHuu":[{"ten":"Nhóm tu sĩ dị vực truy bắt Bạch Hổ đằng","tuChuong":"@c1433","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1433","tabs":{"tienTrinh":[{"chuong":"@c1433","loai":"dùng","importance":"normal","giaiDoan":"Truy bắt Bạch Hổ đằng","text":"Nhóm tu sĩ dị vực dùng lưới sao xuyên phá địa tầng để bắt Bạch Hổ đằng, vô tình kéo quan tài đồng lên khỏi lòng đất.","anchor":"là một cái lưới lớn, lấy ngôi sao sa luyện chế mà thành","phamCap":"Không rõ"}]},"nguon":["@c1433"]},{"id":"quan-tai-dong-muc-nat","name":"Quan tài đồng mục nát","cn":"","aliases":[],"category":"khac","categoryLabel":"Quan tài","phanLoaiPhu":"Quan tài cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"Nứt vỡ","blurb":"Một cỗ quan tài đồng rỉ sét nằm sâu trong nhánh địa mạch Cổ Táng khu dưới Thần Dược sơn mạch. Khi bị lưới sao kéo lên và nứt vỡ, nó để lộ một táng sĩ mang cánh chim mục nát.","detail":"Quan tài đã bị ăn mòn nghiêm trọng và nằm giữa nhiều xương khô dưới lòng đất. Nhóm tu sĩ dị vực vô tình kéo nó lên khi truy bắt Bạch Hổ đằng, khiến táng sĩ bên trong thức tỉnh và bắt đầu đồ sát những kẻ quấy nhiễu.","hinhDang":"Quan tài đồng rỉ sét loang lổ, bị ăn mòn và gần như mục nát.","vatLieu":"Đồng","nguonGoc":"Địa mạch Cổ Táng khu lan vào Thần Dược sơn mạch.","dacDiem":"Chứa táng sĩ cánh mục nát vẫn có ý thức.","capNhatToi":"@c1433","tabs":{"tienTrinh":[{"chuong":"@c1433","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị kéo khỏi địa mạch","text":"Quan tài đồng bị lưới sao kéo lên, nứt vỡ và làm lộ táng sĩ cánh mục nát bên trong.","anchor":"còn có một cái rỉ sét loang lổ quan tài đồng, bị ăn mòn không được dạng","phamCap":"Không rõ"}]},"nguon":["@c1433"]},{"id":"quan-tai-dong-trong-di-tuong-dai-la-kiem-thai","name":"Quan tài đồng trong dị tượng Đại La kiếm thai","cn":"","aliases":["Quan tài đồng trong dị tượng Kiếm Thai"],"category":"khac","categoryLabel":"Dị tượng vật phẩm","phamCap":"Không rõ","soHuu":[],"trangThai":"Chỉ xuất hiện trong dị tượng","blurb":"Quan tài đồng xuất hiện trong dị tượng của Đại La kiếm thai giữa cảnh táng khu nhuốm máu.","detail":"Một hình người ngồi trên quan tài đồng khiến táng sĩ thành kính quỳ lạy. Danh tính của hình người và bản chất của quan tài chưa được xác nhận.","phanLoaiPhu":"Dị tượng","hinhDang":"Quan tài bằng đồng có hình người ngồi phía trên.","dacDiem":"Hình người trên quan tài là đối tượng được táng sĩ thành kính cúng bái.","tabs":{"tienTrinh":[{"chuong":"@c1435","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện trong dị tượng kiếm","text":"Quan tài đồng cùng hình người ngồi phía trên hiện ra trong dị tượng của Đại La kiếm thai và khiến táng sĩ quỳ lạy.","anchor":"xác thực nói nó là ở đối với quan tài đồng trên đạo hình người kia sinh linh cúng bái!"}]},"capNhatToi":"@c1435","nguon":["@c1435"]},{"id":"bao-dich-ho-vang","name":"Bảo dịch hồ vàng","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Bảo dịch","phamCap":"Không rõ","soHuu":[],"trangThai":"Còn trong hồ vàng","blurb":"Bảo dịch màu vàng trong địa quật có hiệu quả chữa trị thương thế rất mạnh.","detail":"Đại tu sĩ Độn Nhất ngâm mình trong hồ và nhờ bảo dịch giải quyết hoàn toàn thương thế chỉ sau một khoảng thời gian ngắn.","hinhDang":"Chất lỏng màu vàng chứa trong hồ ở địa quật","uyLuc":"Có thể chữa khỏi thương thế của một đại tu sĩ Độn Nhất trong thời gian ngắn.","dacDiem":"Hiệu quả chữa trị được mô tả là khó tưởng tượng.","congNang":["Chữa trị nhanh chóng và giải quyết hoàn toàn thương thế của đại tu sĩ Độn Nhất."],"chuSoHuu":[{"ten":"Đại tu sĩ Độn Nhất dị vực","tuChuong":"@c1436","denChuong":"@c1436","cachCoDuoc":"Bế quan trong hồ vàng để hấp thu bảo dịch","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1436","loai":"dùng","importance":"normal","giaiDoan":"Chữa khỏi thương thế","text":"Đại tu sĩ Độn Nhất dùng bảo dịch trong hồ vàng để chữa khỏi thương thế sau lần giao chiến trước.","anchor":"Cái này kim sắc trong hồ, có vô thượng bảo dịch, hắn hiệu quả không cách nào tưởng tượng, mặc dù mới đi qua không có bao lâu thời gian, nhưng là hắn đã giải quyết bản thân vấn đề.","phamCap":"Không rõ"}]},"capNhatToi":"@c1436","nguon":["@c1436"]},{"id":"van-vat-tho","name":"Vạn vật thổ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Thần thổ","phamCap":"Táng thổ quý báu","soHuu":["Thạch Hạo"],"trangThai":"Đang được giữ trong chậu sành","blurb":"Một loại thần thổ có thể duy trì vạn vật bất hủ và thai nghén sinh cơ. Táng sĩ xác nhận đây là một trong những loại táng thổ quý báu nhất.","detail":"Vạn vật thổ được Thạch Hạo dùng để trồng Thiên Thần Thụ màu vàng. Khi nhìn thấy nó, táng sĩ thần bí lập tức nhận ra mối liên hệ với táng thổ của Cổ Táng Khu.","phanLoaiPhu":"Táng thổ","nguonGoc":"Cổ Táng Khu","uyLuc":"Có thể duy trì vạn vật bất hủ và thai nghén sinh mệnh.","dacDiem":"Được táng sĩ nhận định là một trong những loại táng thổ quý báu nhất.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1437","congNang":["Duy trì vạn vật bất hủ.","Thai nghén sinh cơ và sinh mệnh."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1437","denChuong":"","cachCoDuoc":"Đã mang theo trong chậu sành khi tiến vào dãy núi.","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1437","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhận diện là táng thổ","text":"Táng sĩ nhận ra vạn vật thổ và xác nhận đây là một loại táng thổ quý báu.","anchor":"Đây là trong truyền thuyết quý báu nhất táng thổ một trong"}]},"nguon":["@c1437"]},{"id":"thien-than-thu-mau-vang","name":"Thiên Thần Thụ màu vàng","cn":"","aliases":[],"category":"khac","categoryLabel":"Thần thụ","phamCap":"Thiên Thần Thụ","soHuu":["Thạch Hạo"],"trangThai":"Được trồng trong chậu vạn vật thổ","blurb":"Một trong bốn cây Thiên Thần Thụ có thể hợp nhất thành Thiên Tiên thụ. Quả của cây được truyền rằng có thể giúp người ăn lập tức trở thành thiên thần.","detail":"Cây thần màu vàng có khả năng cảm ứng những đoạn mẫu căn cùng nguồn. Thạch Hạo mang nó ra để dò tìm đồng loại trong Thần Dược sơn mạch.","phanLoaiPhu":"Thần dược thụ","dacDiem":"Có thể cảm ứng và gọi những đoạn mẫu căn cùng nguồn.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1437","congNang":["Quả của cây có thể giúp người ăn lập tức trở thành thiên thần.","Phát khí tức để cảm ứng đoạn mẫu căn cùng nguồn."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1437","denChuong":"","cachCoDuoc":"Mang theo trong chậu sành chứa vạn vật thổ.","trangThai":"dang-co"}],"dinhDanh":"goc","boCha":"bon-cay-thien-than-thu","tabs":{"tienTrinh":[{"chuong":"@c1437","loai":"dùng","importance":"normal","giaiDoan":"Dò tìm mẫu căn","text":"Thạch Hạo dùng cây màu vàng phát khí tức để tìm đoạn mẫu căn đang ẩn trong dãy núi.","anchor":"Thiên Thần Thụ trái cây, một khi nuốt vào, có thể lập tức thành vì là thiên thần"}]},"nguon":["@c1437"]},{"id":"thien-than-thu-mau-do-tham","name":"Thiên Thần Thụ màu đỏ thẫm","cn":"","aliases":[],"category":"khac","categoryLabel":"Thần thụ","phamCap":"Thiên Thần Thụ","soHuu":[],"trangThai":"Bị lực lượng dị vực vây chặn","blurb":"Một đoạn mẫu căn thần thụ toàn thân đỏ thẫm, có lá như chu tước tung bay. Cây có thể điều động núi sông địa mạch để đào thoát.","detail":"Cây đỏ đáp lại khí tức của Thiên Thần Thụ màu vàng nhưng bỏ chạy khi phát hiện táng sĩ. Trong lúc đào thoát, nó bị đoàn sinh linh dị vực chặn lại.","phanLoaiPhu":"Thần dược thụ","hinhDang":"Toàn thân đỏ thẫm, phiến lá như chu tước tung bay giữa ánh lửa.","uyLuc":"Điều động núi sông địa mạch để di chuyển với tốc độ vượt mức Súc Địa Thành Thốn.","dacDiem":"Khí thế không kém Thiên Thần Thụ màu vàng.","capNhatToi":"@c1437","congNang":["Điều động núi sông địa mạch để chạy trốn cực nhanh."],"dinhDanh":"goc","boCha":"bon-cay-thien-than-thu","tabs":{"tienTrinh":[{"chuong":"@c1437","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ diện và đào thoát","text":"Cây đỏ lộ diện với những phiến lá tựa chu tước, sau đó nhổ rễ chạy trốn và bị lực lượng dị vực vây chặn.","anchor":"phiến lá dường như chu tước tung bay, mang theo đầy trời ánh lửa"}]},"nguon":["@c1437"]},{"id":"thien-tien-thu","name":"Thiên Tiên thụ","cn":"","aliases":[],"category":"khac","categoryLabel":"Trường sinh tiên dược thụ","phamCap":"Trường sinh tiên dược","soHuu":[],"trangThai":"Chưa hợp nhất","blurb":"Hình thái hoàn chỉnh được cho là sinh ra khi bốn cây Thiên Thần Thụ hợp nhất. Quả của cây theo truyền thuyết có thể giúp người ăn lập tức trở thành chân tiên.","detail":"Thiên Tiên thụ hiện được nhắc đến như mục tiêu hợp nhất bốn đoạn Thiên Thần Thụ. Giá trị của trường sinh tiên dược thụ này khiến Thạch Hạo quyết tâm tìm đủ các đoạn mẫu căn.","dacDiem":"Do bốn cây Thiên Thần Thụ hợp nhất thành một thể.","capNhatToi":"@c1437","congNang":["Quả của cây được truyền rằng có thể giúp người ăn lập tức trở thành chân tiên."],"tabs":{"tienTrinh":[{"chuong":"@c1437","loai":"nhắc tới","importance":"bridge","giaiDoan":"Hé lộ hình thái hợp nhất","text":"Thiên Tiên thụ được nhắc đến như hình thái hoàn chỉnh của bốn cây Thiên Thần Thụ.","anchor":"một khi ăn nó, có thể lập tức thành làm thật tiên"}]},"nguon":["@c1437"]},{"id":"mau-can-thien-tien-thu","name":"Mẫu căn Thiên Tiên thụ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Mẫu căn thần thụ","phamCap":"Không rõ","soHuu":[],"trangThai":"Bị chia thành bốn đoạn","blurb":"Mẫu căn của Thiên Tiên thụ từng bị cắt thành bốn đoạn, tạo thành những cây Thiên Thần Thụ riêng biệt. Nguyên nhân chia cắt chưa được xác định.","detail":"Có hai giả thuyết về việc mẫu căn bị chia cắt: do một sức mạnh trong cõi u minh hoặc do đại chiến lan tới. Thiên Thần Thụ màu vàng và cây đỏ thẫm là những đoạn cùng nguồn có thể cảm ứng lẫn nhau.","dacDiem":"Từng bị cắt thành bốn đoạn có khả năng cảm ứng khí tức cùng nguồn.","capNhatToi":"@c1437","congNang":["Các đoạn mẫu căn cùng nguồn có thể cảm ứng lẫn nhau."],"dinhDanh":"goc","laBo":true,"thanhVien":[{"id":"thien-than-thu-mau-vang","vaiTro":"Một đoạn mẫu căn màu vàng"},{"id":"thien-than-thu-mau-do-tham","vaiTro":"Một đoạn mẫu căn màu đỏ thẫm"}],"tabs":{"tienTrinh":[{"chuong":"@c1437","loai":"xuất hiện","importance":"major","giaiDoan":"Hé lộ bốn đoạn","text":"Mẫu căn Thiên Tiên thụ được hé lộ đã bị cắt thành bốn đoạn và tồn tại dưới hình thái các cây Thiên Thần Thụ.","anchor":"mẫu căn cắt thành bốn đoạn"}]},"nguon":["@c1437"]},{"id":"bach-kiep-thang-troi","name":"Bách kiếp thang trời","cn":"","aliases":["Trăm Kiếp Thang Trời"],"category":"phap-bao","categoryLabel":"Vô thượng chí bảo","phamCap":"Vô thượng chí bảo","soHuu":["Dị Vực"],"trangThai":"Đang được lực lượng Dị Vực sử dụng","blurb":"Chí bảo được Dị Vực mang tới để hỗ trợ các đội ngũ tiến vào Thần Dược Sơn Mạch.","detail":"Bách kiếp thang trời có khả năng đưa người thuận lợi tiến vào Thần Dược Sơn Mạch, giúp Dị Vực tiếp tục điều động lực lượng vào khu vực.","phanLoaiPhu":"Chí bảo hỗ trợ di chuyển","congNang":["Đưa người thuận lợi tiến vào Thần Dược Sơn Mạch tại @c1438."],"chuHienThoi":"Dị Vực","chuSoHuu":[{"ten":"Dị Vực","tuChuong":"@c1438","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"capNhatToi":"@c1438","tabs":{"tienTrinh":[{"chuong":"@c1438","loai":"xuất hiện","importance":"normal","giaiDoan":"Hỗ trợ tiến vào núi","text":"Dị Vực mang Bách kiếp thang trời tới để đưa các đội ngũ tiến vào Thần Dược Sơn Mạch.","anchor":"đây là vô thượng chí bảo, có thể mang theo bọn ngươi thuận lợi tiến vào Thần Dược Sơn Mạch","phamCap":"Vô thượng chí bảo"}]},"nguon":["@c1438"]},{"id":"tien-duoc","name":"Tiên dược","cn":"","aliases":[],"category":"khac","categoryLabel":"Linh dược","phamCap":"Tiên dược","soHuu":[],"trangThai":"Tồn tại trong Cổ Táng Khu","blurb":"Linh dược quý hiếm sinh trưởng an toàn trong Cổ Táng Khu, được xác nhận có nhiều hơn một cây.","detail":"Nữ táng sĩ xác nhận từng nhìn thấy nhiều cây tiên dược trong Cổ Táng Khu. Thạch Hạo muốn tìm chúng để mang về Đế Quan, nhưng táng sĩ cho rằng chúng có thể hữu dụng với những tồn tại sâu trong táng khu và không đồng ý dẫn đường.","nguonGoc":"Cổ Táng Khu","congNang":["Có giá trị đối với các cường giả và những tồn tại sâu trong Cổ Táng Khu."],"capNhatToi":"@c1441","tabs":{"tienTrinh":[{"chuong":"@c1441","loai":"xuất hiện","importance":"normal","giaiDoan":"Được xác nhận tồn tại","text":"Táng sĩ xác nhận Cổ Táng Khu có nhiều hơn một cây tiên dược, khiến Thạch Hạo nảy ý định tìm bắt và mang về Đế Quan.","anchor":"Có, hơn nữa không ngừng một cây, ta thấy qua"}]},"nguon":["@c1441"]},{"id":"tien-thu","name":"Tiên thụ","cn":"","aliases":[],"category":"khac","categoryLabel":"Linh thụ","phamCap":"Tiên thụ","soHuu":[],"trangThai":"Được nhắc tới","blurb":"Loại linh thụ quý hiếm từng xuất hiện trong Cổ Táng Khu. Một đại nhân tại đó từng chém một cây để chế thành quan tài.","detail":"Táng sĩ kể rằng nàng từng tận mắt thấy một vị đại nhân chém tiên thụ làm quan tài. Câu chuyện cho thấy loại cây quý hiếm này từng bị một tồn tại sâu trong Cổ Táng Khu sử dụng như vật liệu.","nguonGoc":"Cổ Táng Khu","congNang":["Thân cây có thể được dùng để chế tạo quan tài."],"capNhatToi":"@c1441","tabs":{"tienTrinh":[{"chuong":"@c1441","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ cách sử dụng","text":"Táng sĩ kể lại việc một đại nhân trong Cổ Táng Khu từng chém một cây tiên thụ để làm quan tài.","anchor":"từng nhìn thấy một vị đại nhân chém một cây tiên thụ làm quan tài"}]},"nguon":["@c1441"]},{"id":"chien-xa-ri-sat-trong-tang-mach","name":"Chiến xa rỉ sắt trong táng mạch","cn":"","category":"khac","categoryLabel":"Phương tiện truyền tống","phamCap":"","soHuu":["Nữ Táng Sĩ"],"trangThai":"đang sử dụng","blurb":"Một chiến xa cũ phủ rỉ sắt nằm trong địa mạch đen của táng khu.","detail":"Chiến xa đưa Nữ Táng Sĩ và Thạch Hạo biến mất khỏi một đoạn táng mạch rồi xuất hiện tại vùng địa mạch xa xôi có nhiều quan tài đá.","phanLoaiPhu":"Phương tiện di chuyển trong táng mạch","hinhDang":"Chiến xa cũ phủ rỉ sắt.","congNang":["Dịch chuyển người sử dụng qua khoảng cách cực xa trong táng mạch."],"dacDiem":"Hoạt động tương tự một phương tiện truyền tống không gian.","chuHienThoi":"Nữ Táng Sĩ","chuSoHuu":[{"ten":"Nữ Táng Sĩ","tuChuong":"@c1442","denChuong":"","cachCoDuoc":"Sử dụng chiến xa đặt trong táng mạch.","trangThai":"đang sử dụng"}],"capNhatToi":"@c1442","tabs":{"tienTrinh":[{"chuong":"@c1442","loai":"dùng","importance":"normal","giaiDoan":"Vượt qua táng mạch","text":"Nữ Táng Sĩ và Thạch Hạo bước lên chiến xa rồi được đưa tới một vùng địa mạch cách đó cực xa.","anchor":"Này tương tự với không gian truyền tống, vượt qua không biết bao nhiêu vạn dặm!"}]},"nguon":["@c1442"]},{"id":"guong-dong-cua-thieu-nu-co-canh-trang","name":"Gương đồng của thiếu nữ có cánh trắng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Không rõ","soHuu":["Nữ Táng Sĩ"],"trangThai":"Nguyên vẹn","blurb":"Một bảo cụ rạng ngời được Nữ Táng Sĩ đưa cho Thạch Hạo. Mặt gương phản chiếu rõ trạng thái chỉ còn bạch cốt và linh hồn chi hỏa của hắn.","detail":"Gương đồng có ánh sáng rực rỡ và được mô tả là một bảo cụ mạnh mẽ. Khi Thạch Hạo soi gương, nó cho thấy trong sọ của bộ xương trắng vẫn có linh hồn chi hỏa lập lòe.","phanLoaiPhu":"Gương đồng","hinhDang":"Một khối gương đồng rạng ngời rực rỡ","dacDiem":"Bảo cụ mạnh mẽ có thể phản chiếu trạng thái thân thể và linh hồn chi hỏa.","chuHienThoi":"Nữ Táng Sĩ","congNang":["Phản chiếu bộ xương trắng cùng linh hồn chi hỏa của Thạch Hạo @c1443"],"chuSoHuu":[{"ten":"Nữ Táng Sĩ","tuChuong":"@c1443","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1443","tabs":{"tienTrinh":[{"chuong":"@c1443","loai":"dùng","importance":"normal","giaiDoan":"Kiểm tra thân thể Thạch Hạo","text":"Nữ Táng Sĩ đưa gương đồng cho Thạch Hạo, qua đó hắn nhìn thấy hình dạng bạch cốt và linh hồn chi hỏa của mình.","anchor":"Nàng lấy ra một khối gương đồng, rạng ngời rực rỡ, đưa cho Thạch Hạo, đây là một khối mạnh mẽ bảo cụ"}]},"nguon":["@c1443"]},{"id":"bia-da-co-cua-tang-vuc-thanh-dia","name":"Bia đá cổ của Táng Vực Thánh địa","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm kiến trúc","phamCap":"Không rõ","soHuu":[],"trangThai":"Hiện lên tại Thánh địa","blurb":"Những bia đá cổ khổng lồ trồi lên khi Táng Vực Thánh địa thức tỉnh. Chúng khắc chữ cổ khó nhận biết và mang đại đạo khí tức đáng sợ.","detail":"Mỗi bia đá đều lớn hơn núi, vươn vào tầng mây và quanh quẩn đại đạo khí tức. Nữ Táng Sĩ xem sự xuất hiện của chúng là dấu hiệu truyền thuyết Hóa Điệp trở về đã ứng nghiệm.","phanLoaiPhu":"Bia đá cổ","hinhDang":"Những bia đá khổng lồ chọc vào tầng mây","dacDiem":"Khắc chữ cổ khó nhận biết và quanh quẩn đại đạo khí tức.","congNang":["Mang chữ cổ và đạo vận gắn với sự thức tỉnh của Táng Vực Thánh địa @c1443"],"capNhatToi":"@c1443","tabs":{"tienTrinh":[{"chuong":"@c1443","loai":"xuất hiện","importance":"normal","giaiDoan":"Thánh địa thức tỉnh","text":"Nhiều bia đá cổ khổng lồ trồi lên khỏi mặt đất khi Táng Vực Thánh địa sống lại.","anchor":"một khối lại một khối to lớn bia đá hiện lên, chọc vào trong tầng mây, đều quanh quẩn đại đạo khí tức"}]},"nguon":["@c1443"]},{"id":"tien-kim-bao-y-cua-dao-si-beo","name":"Tiên kim bảo y của đạo sĩ béo","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo y","phanLoaiPhu":"Chiến giáp dệt bằng tơ Tiên kim","phamCap":"Vô thượng bảo y","soHuu":["Tào Vũ Sinh"],"trangThai":"Tổn hại và nhuốm máu","blurb":"Bảo y của Tào Vũ Sinh được dệt bằng tơ nhỏ từ nhiều loại Tiên kim. Nó đã bị xé rách và nhuốm máu sau một trận chiến dữ dội.","detail":"Đạo sĩ béo mặc đạo bào rộng được bện từ tơ nhỏ của nhiều loại Tiên kim. Bảo y vốn được mô tả là vô thượng nhưng tại thời điểm xuất hiện đã hư hại và mang nhiều vết máu.","hinhDang":"Đạo bào rộng","vatLieu":"Tơ nhỏ từ nhiều loại Tiên kim","uyLuc":"Được xem là vô thượng bảo y.","dacDiem":"Bị tổn hại và dính máu sau chiến đấu.","chuHienThoi":"Tào Vũ Sinh","congNang":["Dùng làm bảo y hoặc chiến giáp bảo vệ người mặc."],"chuSoHuu":[{"ten":"Tào Vũ Sinh","tuChuong":"@c1444","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1444","tabs":{"tienTrinh":[{"chuong":"@c1444","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bảo y tổn hại","text":"Tào Vũ Sinh xuất hiện trong bảo y Tiên kim đã rách nát và nhuốm máu sau chiến đấu.","anchor":"Hắn ăn mặc đạo bào rất rộng rãi, là lấy nhiều loại Tiên kim tia nhỏ bện mà thành, chính là vô thượng bảo y, chỉ là hiện nay lại tổn hại, mang theo vết máu."}]},"nguon":["@c1444"]},{"id":"tien-gia-giap-tru-cua-tao-vu-sinh","name":"Tiên gia giáp trụ của Tào Vũ Sinh","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Giáp trụ","phanLoaiPhu":"Tiên gia giáp trụ","phamCap":"Không rõ","soHuu":["Tào Vũ Sinh"],"trangThai":"hong","blurb":"Bộ giáp trụ của Tào Vũ Sinh bị sấm sét và thiên phạt đánh phá nát trong cuộc trò chuyện xuyên năm tháng.","detail":"Giáp trụ bảo vệ Tào Vũ Sinh khi hắn cố tiết lộ tương lai cho Thạch Hạo, nhưng không chịu nổi thiên phạt và bị đánh vỡ.","dacDiem":"Bị thiên phạt phá nát khi Tào Vũ Sinh tiết lộ tin tức từ hậu thế.","chuHienThoi":"Tào Vũ Sinh","chuSoHuu":[{"ten":"Tào Vũ Sinh","tuChuong":"@c1445","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Giáp trụ đã hư hỏng"}],"capNhatToi":"@c1445","dinhDanh":"goc","nguon":["@c1445"]},{"id":"mon","name":"Môn","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật hoặc thông đạo chưa xác định","phamCap":"Không rõ","soHuu":[],"trangThai":"Không rõ","blurb":"Một vật hoặc thông đạo chưa xác định liên quan đến cuộc đối thoại xuyên năm tháng giữa Thạch Hạo và Tào Vũ Sinh.","detail":"Tào Vũ Sinh dùng đại pháp lực khiến đệ tử đầu trọc hiện hình trước Môn, qua đó người đệ tử và Thạch Hạo có thể nhìn thấy nhau ở hai bờ thời gian.","dacDiem":"Liên quan việc nhìn thấy và đối thoại qua hai bờ năm tháng.","congNang":["Cho phép người ở hai thời đại nhìn thấy nhau khi được Tào Vũ Sinh dùng đại pháp lực hỗ trợ."],"capNhatToi":"@c1446","tabs":{"tienTrinh":[{"chuong":"@c1446","loai":"xuất hiện","importance":"bridge","giaiDoan":"Hiện hình xuyên thời gian","text":"Môn xuất hiện như điểm liên kết để đệ tử đầu trọc và Thạch Hạo nhìn thấy nhau qua hai bờ thời gian.","anchor":"Không chỉ có Thạch Hạo nhìn thấy hắn, mà hắn cũng nhìn thấy Thạch Hạo, hết thảy đều là Tào Vũ Sinh gây nên, vận dụng đại pháp lực để hắn hiện hình với \"Môn\" trước."}]},"nguon":["@c1446"]},{"id":"truong-sinh-thu","name":"Trường Sinh Thụ","cn":"","aliases":["Cây Tiên thụ tối cổ","Tiên Thụ bị chặt thân"],"category":"dan-duoc","categoryLabel":"Trường Sinh dược","phanLoaiPhu":"Trường Sinh dược dạng cây","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang tái sinh từ gốc từng bị chặt","blurb":"Trường Sinh dược dạng cổ thụ có tuổi đời cực kỳ lâu đời, được phát hiện đang mọc lại trên một đạo đài cổ trong tế tự Thánh địa.","detail":"Cây cao hơn một mét, mọc từ gốc từng bị chặt trong khe nứt của đạo đài, tỏa ngũ sắc tiên quang và mang những chiếc lá khác nhau về màu sắc lẫn hình dạng. Tử Phủ dịch và địa tủy từ tổ mạch linh căn hội tụ quanh nơi cây cắm rễ.","hinhDang":"Cổ thụ cao hơn một mét với lá khác màu sắc và hình dạng","nguonGoc":"Cây Tiên thụ có tuổi đời cổ xưa nhất được Nữ Táng Sĩ nhận ra tại tế tự Thánh địa","uyLuc":"Có thể trợ giúp Táng Sĩ ngộ đạo khi tu hành bên dưới","dacDiem":"Cổ căn tái sinh, tỏa ngũ sắc tiên quang và mang nhiều loại lá khác nhau","congNang":["Trợ giúp Táng Sĩ ngộ đạo khi tu hành bên dưới cây"],"chuHienThoi":"","chuSoHuu":[],"capNhatToi":"@c1447","tabs":{"tienTrinh":[{"chuong":"@c1447","loai":"xuất hiện","importance":"major","giaiDoan":"Tái sinh từ cổ căn","text":"Trường Sinh Thụ tối cổ được phát hiện đang tái sinh từ gốc từng bị chặt trong khe nứt của đạo đài.","anchor":"Lại là nó, cái kia cây tuổi tác tối cổ Tiên thụ!","phamCap":"Trường Sinh dược"}]},"nguon":["@c1447"]},{"id":"dao-thai-tan-ta","name":"Đạo thai tàn tạ","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo đài cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"tàn tạ nhưng còn thông linh","blurb":"Đạo thai cổ nơi một vô thượng táng sĩ từng ngồi quan, vẫn lưu giữ đạo vận và sức mạnh tự bảo vệ.","detail":"Khi Thạch Hạo tìm cách bắt Trường Sinh Thụ, Đạo thai đánh văng bảo cụ, làm nứt hổ khẩu hắn và hiện ra một khuôn mặt lạnh lùng trên vách đá.","phanLoaiPhu":"Đạo đài cổ","uyLuc":"Có thể đánh văng bảo cụ và làm nứt hổ khẩu Thạch Hạo.","dacDiem":"Thông linh, trên vách đá có thể hiện ra một khuôn mặt mơ hồ và lạnh lùng.","congNang":["Đẩy lui kẻ xâm phạm và bảo vệ khu vực Đạo thai tại @c1448."],"capNhatToi":"@c1448","tabs":{"tienTrinh":[{"chuong":"@c1448","loai":"xuất hiện","importance":"normal","giaiDoan":"Phản kích người xâm phạm","text":"Đạo thai đánh văng bảo cụ của Thạch Hạo, làm hắn bị thương và hiện một khuôn mặt lạnh lùng trên vách đá.","anchor":"Ở cái kia Đạo thai tàn tạ trên vách đá, lại có một tấm mơ hồ khuôn mặt hiện lên, nhìn không rõ ràng, thế nhưng xác thực khiến người ta cảm thấy nó lạnh lùng."}]},"nguon":["@c1448"]},{"id":"co-do-da-thu-cua-de-quan","name":"Cổ đồ da thú của Đế quan","cn":"","aliases":["Tấm da thú đồ tại Đế Quan"],"category":"khac","categoryLabel":"Bản đồ","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"dang-co","blurb":"Một cổ đồ da thú có ký hiệu đầu lâu đen đánh dấu vùng tạo hóa.","detail":"Thạch Hạo đối chiếu ký hiệu đầu lâu trên cổ đồ với những đốm đất đen trong ách thổ, qua đó xác định vùng tạo hóa nằm giữa Thần Dược Sơn Mạch, Thiên Thú Sâm Lâm và cổ táng khu.","phanLoaiPhu":"Bản đồ","dacDiem":"Có ký hiệu đầu lâu đen giống hoa văn xuất hiện trong ách thổ.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1449","congNang":["Đánh dấu vị trí vùng tạo hóa giữa ba cổ địa."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1449","denChuong":"","cachCoDuoc":"Đã xem và ghi nhớ cổ đồ tại Đế Quan.","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1449","loai":"dùng","importance":"normal","giaiDoan":"Đối chiếu ký hiệu","text":"Ký hiệu đầu lâu trên cổ đồ được đối chiếu với hoa văn đất đen tại ách thổ, giúp Thạch Hạo xác định đúng vùng tạo hóa.","anchor":"đi theo Đế Quan bên trong bản thân nhìn thấy tấm kia da thú đồ trên đánh dấu giống như đúc"}]},"nguon":["@c1449"]},{"id":"chi-bao-cua-dai-nhan-tre-tuoi-de-toc","name":"Chí bảo của đại nhân trẻ tuổi Đế tộc","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"dang-co","blurb":"Một chí bảo chưa rõ tên được đại nhân trẻ tuổi Đế tộc mang vào ách thổ.","detail":"Ba cao thủ Vô Úy Sư Tử cho biết người sở hữu đã bỏ vốn lớn và dựa vào chí bảo này để vượt qua đường hiểm, tiến vào ách thổ trước những người khác.","chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc","capNhatToi":"@c1449","congNang":["Hỗ trợ người sở hữu vượt qua đường nguy hiểm để tiến vào ách thổ."],"chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1449","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1449","loai":"nhắc tới","importance":"normal","giaiDoan":"Tiến vào ách thổ","text":"Chí bảo được tiết lộ là phương tiện giúp đại nhân trẻ tuổi Đế tộc thông qua đường hiểm và vào ách thổ trước.","anchor":"Trên người hắn có chí bảo, lần này hoa rơi xuống tiền vốn lớn"}]},"nguon":["@c1449"]},{"id":"sach-co-tan-khuyet-cua-du-da","name":"Sách cổ tàn khuyết của Du Đà","cn":"","aliases":[],"category":"khac","categoryLabel":"Sách cổ","phamCap":"Không rõ","soHuu":["Du Đà"],"trangThai":"Tàn khuyết","blurb":"Bộ sách cổ Du Đà đào được trong Cổ Táng Khu, ghi lại một địa điểm thần bí có chôn đồ cổ.","detail":"Nội dung còn lại của sách chỉ dẫn tới một địa điểm thần bí, nhưng không xác nhận vật được chôn là kinh thư, táng khí, sức mạnh đặc biệt hay đạo thể vô song.","dacDiem":"Tàn khuyết và có ghi chép về một địa điểm thần bí chôn đồ cổ.","chuHienThoi":"Du Đà","chuSoHuu":[{"ten":"Du Đà","tuChuong":"@c1450","denChuong":"","cachCoDuoc":"Đào được trong Cổ Táng Khu","trangThai":"Được ghi nhận là người thu được"}],"congNang":["Lưu lại chỉ dẫn về một địa điểm thần bí chôn đồ cổ."],"capNhatToi":"@c1450","nguon":["@c1450"]},{"id":"binh-bat-ran-nut-cua-co-tang","name":"Bình bát rạn nứt của cổ tăng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Cổ bảo rạn nứt","soHuu":["Ba sư tử vàng thuộc mạch Vô Úy Sư Tử"],"trangThai":"hong","blurb":"Một bình bát cổ tăng phủ đầy vết rạn, có thể phóng lớn và hút sinh linh vào vùng hỗn độn.","detail":"Bình bát từng hút nửa người Thạch Hạo vào trong, nhưng bị kiếm thai xuyên thủng và phát nổ. Mảnh vỡ của nó bắn ngược, góp phần khiến ba Hoàng Kim sư tử bị thương nặng.","phanLoaiPhu":"Pháp khí cổ tăng","hinhDang":"Bình bát có nhiều vết rạn","uyLuc":"Có thể khiến Thạch Hạo nhất thời khó tránh khỏi lực hút.","dacDiem":"Mang hỗn độn khí và đã bị rạn nứt trước khi giao chiến.","chuHienThoi":"Không còn","congNang":["Phóng lớn và hút sinh linh vào vùng hỗn độn bên trong."],"chuSoHuu":[{"ten":"Ba sư tử vàng thuộc mạch Vô Úy Sư Tử","tuChuong":"@c1450","denChuong":"@c1450","cachCoDuoc":"Không rõ","trangThai":"Pháp khí đã bị phá hủy"}],"capNhatToi":"@c1450","tabs":{"tienTrinh":[{"chuong":"@c1450","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị kiếm thai phá hủy","text":"Bình bát hút nửa người Thạch Hạo vào vùng hỗn độn nhưng bị kiếm thai xuyên thủng rồi nổ tung, khiến các mảnh vỡ bắn vào ba Hoàng Kim sư tử.","phamCap":"Cổ bảo rạn nứt","anchor":"một cây kiếm thai vọt lên, trực tiếp đâm thủng bình bát, sau đó pháp lực, ầm ầm một tiếng, cái kia bảo cụ nổ tung"}]},"nguon":["@c1450"]},{"id":"hang-ma-xu-ran-nut-cua-co-tang","name":"Hàng Ma Xử rạn nứt của cổ tăng","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Cổ bảo rạn nứt","soHuu":["Ba sư tử vàng thuộc mạch Vô Úy Sư Tử"],"trangThai":"hong","blurb":"Một Hàng Ma Xử tử kim sắc của cổ tăng, mang nhiều vết rạn nhưng khi kích hoạt vẫn có thể làm thiên địa nứt ra.","detail":"Một Hoàng Kim sư tử dùng Hàng Ma Xử đánh xuống Thạch Hạo. Hắn dùng tay không ngăn lại rồi liên tục tung quyền khiến các vết rạn mở rộng, cuối cùng phá hủy hoàn toàn pháp bảo.","phanLoaiPhu":"Pháp bảo cổ tăng","hinhDang":"Hàng Ma Xử tử kim sắc phủ nhiều vết rạn","uyLuc":"Khi được kích hoạt có thể làm thiên địa nứt ra.","dacDiem":"Đã mang nhiều vết rạn trước khi bị Thạch Hạo đánh vỡ.","chuHienThoi":"Không còn","congNang":["Đánh xuống mục tiêu bằng sức mạnh đủ làm thiên địa nứt ra."],"chuSoHuu":[{"ten":"Ba sư tử vàng thuộc mạch Vô Úy Sư Tử","tuChuong":"@c1450","denChuong":"@c1450","cachCoDuoc":"Không rõ","trangThai":"Pháp bảo đã bị phá hủy"}],"capNhatToi":"@c1450","tabs":{"tienTrinh":[{"chuong":"@c1450","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị quyền lực phá hủy","text":"Hàng Ma Xử bị Thạch Hạo dùng tay không chặn lại rồi liên tục đánh vào, khiến các vết rạn mở rộng cho tới khi pháp bảo nổ tung.","phamCap":"Cổ bảo rạn nứt","anchor":"để mặt trên của nó vết rách cấp tốc mở rộng, cuối cùng răng rắc một tiếng, cũng ở đây nổ tung"}]},"nguon":["@c1450"]},{"id":"tien-diep-cua-truong-sinh-thu","name":"Tiên diệp của Trường Sinh thụ","cn":"","category":"nguyen-lieu","categoryLabel":"Tiên dược liệu","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"dang-co","blurb":"Một chiếc lá do Trường Sinh Thụ chủ động rụng xuống khi bị truy đuổi. Lá chứa sinh cơ mạnh mẽ và khí tức sinh mệnh Tiên đạo.","detail":"Trường Sinh Thụ dùng chiếc Tiên diệp để khiến Thạch Hạo phân tâm trong lúc chạy khỏi ách thổ. Thạch Hạo bắt được chiếc lá, còn cây già nhân cơ hội tiến vào thánh địa rồi chui xuống lòng đất.","phanLoaiPhu":"Lá cây tiên dược","dacDiem":"Chứa sinh cơ phồn thịnh và khí tức sinh mệnh Tiên đạo.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1451","congNang":["Mang theo sinh cơ mạnh mẽ và khí tức sinh mệnh Tiên đạo."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1451","denChuong":"","cachCoDuoc":"Bắt lấy chiếc lá do Trường Sinh Thụ chủ động rụng xuống.","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1451","loai":"đổi chủ","importance":"major","giaiDoan":"Rơi vào tay Thạch Hạo","text":"Trường Sinh Thụ chủ động rụng chiếc Tiên diệp để làm Thạch Hạo phân tâm, nhưng hắn đã bắt được lá và giữ nó trong tay.","anchor":"Hắn đưa tay, một cái đã bắt đến rồi trong tay, lập tức cảm giác được phồn thịnh sinh cơ","phamCap":"Không rõ"}]},"nguon":["@c1451"]},{"id":"nat-ruong-go","name":"Nát rương gỗ","cn":"","aliases":["Rương gỗ cổ trong mộ lớn","Rương gỗ vỡ","Rương gỗ mục","Hòm gỗ mục"],"category":"khac","categoryLabel":"Vật phẩm thần bí","phamCap":"Không rõ","soHuu":[],"trangThai":"Được đại dương màu đen bảo vệ","blurb":"Chiếc rương gỗ cực kỳ cổ xưa xuất hiện từ ngôi mộ lớn màu đỏ sậm. Bề ngoài rách nát nhưng nó tỏa ánh sáng vàng kim nhạt, thần thánh và an lành.","detail":"Nát rương gỗ là mục tiêu mà các Bất Hủ chi Vương dị vực đã hao tổn nhiều phương tiện để tìm kiếm. Sau khi ngôi mộ nứt vỡ, chiếc rương chìm nổi trong kim quang giữa đại dương năng lượng màu đen; bí lực của biển khiến mọi lão binh con rối tiếp cận nó đều hình thần câu diệt.","phanLoaiPhu":"Rương gỗ cổ thần bí","hinhDang":"Một chiếc rương gỗ cổ xưa, rách nát và mục cũ.","dacDiem":"Tỏa ánh sáng vàng kim nhạt mang khí tức thần thánh và an lành.","uyLuc":"Bản thân chiếc rương chưa thể hiện uy lực; đại dương màu đen bao quanh có thể tiêu diệt các lão binh con rối.","chuHienThoi":"Không rõ","congNang":[],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"xuất hiện","importance":"major","giaiDoan":"Chính thức xuất thế","text":"Ngôi mộ lớn màu đỏ sậm nứt vỡ, để lộ chiếc rương gỗ cổ chìm nổi trong kim quang giữa đại dương màu đen.","anchor":"ở trong đó có một cái rương xuất hiện, bị mông lung kim quang bao phủ, ở nơi đó chìm nổi","phamCap":"Không rõ"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"bi-khi-cua-bat-huu-chi-vuong","name":"Bí khí của Bất Hủ chi Vương","cn":"","category":"phap-bao","categoryLabel":"Bí khí","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"Được dùng trong kế hoạch mở mộ","blurb":"Những bí khí do Du Đà, An Lan và các tồn tại cùng cấp luyện chế để hỗ trợ đoàn dị vực phá giải ách thổ.","detail":"Các bí khí này là phương tiện chủ chốt giúp đoàn dị vực mở nơi cất chiếc rương gỗ cổ. Hình dạng, số lượng và công năng riêng của từng bí khí chưa được nêu rõ.","nguonGoc":"Do Du Đà, An Lan và các Bất Hủ chi Vương dị vực luyện chế.","chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc","congNang":["Hỗ trợ phá giải và mở nơi cất chiếc rương gỗ cổ."],"chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1452","denChuong":"","cachCoDuoc":"Được các Bất Hủ chi Vương dị vực ban cho để thực hiện kế hoạch.","trangThai":"Đang sử dụng"}],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"dùng","importance":"normal","giaiDoan":"Hỗ trợ mở nơi cất rương","text":"Đoàn dị vực sử dụng các bí khí do Du Đà, An Lan và những Bất Hủ chi Vương khác luyện chế để khiến mục tiêu trong ách thổ xuất thế.","anchor":"chủ yếu là mang đến Du Đà, An Lan các loại (chờ) người tự mình luyện chế bí khí","phamCap":"Không rõ"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"tran-ky-di-vuc","name":"Trận kỳ dị vực","cn":"","category":"phap-bao","categoryLabel":"Trận kỳ","phamCap":"Không rõ","soHuu":["Dị vực"],"trangThai":"Đã hủy","blurb":"Số lượng lớn trận kỳ được mang từ dị vực tới để phục vụ kế hoạch mở ách thổ. Nhiều trận kỳ bị hủy, trong đó có những cột cờ được đúc bằng Tiên kim.","detail":"Trận kỳ dị vực là một phần trong mức tiêu hao rất lớn để khiến ngôi mộ và chiếc rương xuất thế. Chương không nêu rõ trận pháp cụ thể được các trận kỳ cấu thành.","vatLieu":"Một phần cột cờ được đúc bằng Tiên kim.","dacDiem":"Được mang từ dị vực với số lượng lớn.","chuHienThoi":"Dị vực","congNang":["Tham gia quá trình mở cấm địa và khiến mục tiêu trong ngôi mộ xuất thế."],"chuSoHuu":[{"ten":"Dị vực","tuChuong":"@c1452","denChuong":"@c1452","cachCoDuoc":"Được mang từ dị vực tới ách thổ.","trangThai":"Đã hủy"}],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Tiêu hao khi mở ách thổ","text":"Nhiều trận kỳ dị vực bị hủy trong quá trình mở nơi cất chiếc rương, bao gồm những trận kỳ có cột cờ bằng Tiên kim.","anchor":"cũng không biết có bao nhiêu trận kỳ hủy diệt, vậy cũng là từ dị vực mang tới, không thiếu Tiên kim đúc thành cột cờ","phamCap":"Không rõ"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"tui-da-thu-bao-vat","name":"Túi da thú bảo vật","cn":"","category":"phap-bao","categoryLabel":"Pháp khí chứa người","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc","Chí tôn trẻ tuổi Cô Tộc"],"trangThai":"Đang được sử dụng","blurb":"Hai chiếc túi da thú do Đại nhân trẻ tuổi Đế Tộc và Chí tôn trẻ tuổi Cô Tộc sử dụng để chứa các lão binh con rối.","detail":"Khi được mở, hai túi phóng ra thần hà rực rỡ và thả tổng cộng hai mươi cường giả Cửu Thiên Thập Địa đã bị luyện thành tôi tớ.","hinhDang":"Túi chế từ da thú.","chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc và Chí tôn trẻ tuổi Cô Tộc","congNang":["Chứa và thả các cường giả đã bị luyện thành con rối tôi tớ."],"chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1452","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang có"},{"ten":"Chí tôn trẻ tuổi Cô Tộc","tuChuong":"@c1452","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang có"}],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"dùng","importance":"normal","giaiDoan":"Thả lão binh con rối","text":"Đại nhân trẻ tuổi Đế Tộc và Chí tôn trẻ tuổi Cô Tộc mở hai túi da thú, phóng thần hà và thả tổng cộng hai mươi lão binh con rối.","anchor":"hai người bọn họ trước sau lấy ra một cái da thú bảo túi, buông ra miệng túi, hướng ra phía ngoài thả ra xán lạn thần hà","phamCap":"Không rõ"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"khong-gian-phap-khi-chua-binh-vuong","name":"Không gian pháp khí chứa binh vương","cn":"","category":"phap-bao","categoryLabel":"Pháp khí không gian","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"Đang được sử dụng","blurb":"Pháp khí không gian được Đại nhân trẻ tuổi Đế Tộc dùng để chứa năm lão binh mặc giáp trụ.","detail":"Năm lão binh được thả từ pháp khí này và được gọi là các binh vương. Họ bị ép tiến vào đại dương màu đen lấy rương rồi đều bị bí lực tiêu diệt.","chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc","congNang":["Chứa và thả năm lão binh con rối được gọi là binh vương."],"chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1452","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang có"}],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1452","loai":"dùng","importance":"normal","giaiDoan":"Thả năm binh vương","text":"Đại nhân trẻ tuổi Đế Tộc dùng pháp khí không gian thả năm lão binh mặc giáp trụ để tiếp tục thử vượt đại dương màu đen.","anchor":"hắn cũng lấy ra một cái không gian pháp khí, trực tiếp thả ra năm tên ăn mặc giáp trụ lão Binh","phamCap":"Không rõ"}]},"capNhatToi":"@c1452","nguon":["@c1452"]},{"id":"cot-dai-trieu-hoan","name":"Cốt đài triệu hoán","cn":"","aliases":["Cốt đài tím","Pháp đài xương tím"],"category":"phap-bao","categoryLabel":"Pháp đài","phanLoaiPhu":"Pháp đài triệu hoán","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"Nứt nhưng vẫn hoạt động","blurb":"Pháp đài xương màu tím nhạt dùng để mở cửa đón pháp thể Bất Hủ Chi Vương.","detail":"Cốt đài cao ba thước, phối hợp với trận kỳ, phù hiệu xương, Du Đà chân huyết và triệu hoán kinh. Sau khi được đẩy vào biển năng lượng màu đen, nó bay lên xé rách bầu trời và mở cửa cho pháp thể Du Đà giáng lâm.","hinhDang":"Pháp đài cao ba thước, có màu tím nhạt","vatLieu":"Xương","dacDiem":"Chứa Du Đà chân huyết ở phần trung tâm và vẫn hoạt động sau khi nứt.","chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc","congNang":["Phối hợp với chân huyết và triệu hoán kinh để mở cửa đón pháp thể Bất Hủ Chi Vương."],"chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1453","denChuong":"","cachCoDuoc":"Được giao để thực hiện kế hoạch đoạt rương gỗ vỡ","trangThai":"đang sử dụng"}],"capNhatToi":"@c1453","tabs":{"tienTrinh":[{"chuong":"@c1453","loai":"dùng","importance":"normal","giaiDoan":"Mở cửa triệu hoán","text":"Cốt đài từ biển năng lượng bay lên, xé rách bầu trời và mở một cánh cửa đón pháp thể Du Đà.","anchor":"Đón lấy, nó từ trong biển vọt lên tận trời, xé rách toàn bộ thương vũ, mở ra một cánh cửa, nghênh tiếp Bất Hủ chi Vương giáng lâm!"}]},"nguon":["@c1453"]},{"id":"du-da-chan-huyet","name":"Du Đà chân huyết","cn":"","category":"nguyen-lieu","categoryLabel":"Bất Hủ chân huyết","phamCap":"Bất Hủ Chi Vương","soHuu":["Du Đà","Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"Đã dùng trong nghi thức","blurb":"Một phần chân huyết của Du Đà được giấu trong Cốt đài triệu hoán.","detail":"Chân huyết nhiều màu mang sức mạnh của Bất Hủ Chi Vương. Nó thấm vào tấm da thú ghi triệu hoán kinh và trở thành môi giới dẫn pháp thể Du Đà vượt qua Thiên Uyên.","nguonGoc":"Chân huyết của Du Đà","uyLuc":"Mang sức mạnh vô thượng của Bất Hủ Chi Vương.","dacDiem":"Được cất giấu trong phần trung tâm của Cốt đài triệu hoán.","congNang":["Làm môi giới kích hoạt triệu hoán kinh và dẫn pháp thể Du Đà."],"chuSoHuu":[{"ten":"Du Đà","tuChuong":"@c1453","denChuong":"","cachCoDuoc":"Chân huyết của bản thân","trangThai":"được dùng cho nghi thức"},{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1453","denChuong":"","cachCoDuoc":"Được chuẩn bị sẵn trong Cốt đài triệu hoán","trangThai":"đã sử dụng"}],"capNhatToi":"@c1453","tabs":{"tienTrinh":[{"chuong":"@c1453","loai":"dùng","importance":"normal","giaiDoan":"Kích hoạt chân huyết","text":"Cốt đài nứt ra để lộ một phần Du Đà chân huyết, được dùng làm môi giới cho triệu hoán kinh.","anchor":"Ở cái kia cốt giữa đài, lại cất giấu một điểm Du Đà máu, đó là vô thượng chân huyết, đại biểu sức mạnh không gì sánh nổi."}]},"nguon":["@c1453"]},{"id":"da-thu-ghi-trieu-hoan-kinh","name":"Da thú ghi triệu hoán kinh","cn":"","category":"khac","categoryLabel":"Vật dẫn kinh văn","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"Đã tự thiêu","blurb":"Tấm da thú mang đại đạo văn tự của triệu hoán kinh.","detail":"Tấm da thú bay lên Cốt đài triệu hoán, thấm Du Đà chân huyết rồi tự cháy. Quá trình này phát động tiếng tụng kinh gọi pháp thể Du Đà.","hinhDang":"Tấm da thú ghi đầy đại đạo văn tự","dacDiem":"Các đại đạo văn tự trên bề mặt không thể nhận biết bằng cách thông thường.","congNang":["Mang và kích hoạt Chân kinh triệu hoán Bất Hủ Chi Vương."],"chuHienThoi":"Đã bị thiêu hủy","chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1453","denChuong":"@c1453","cachCoDuoc":"Được chuẩn bị cho nghi thức triệu hoán","trangThai":"đã dùng"}],"capNhatToi":"@c1453","tabs":{"tienTrinh":[{"chuong":"@c1453","loai":"dùng","importance":"normal","giaiDoan":"Tự thiêu kích hoạt","text":"Tấm da thú thấm Du Đà chân huyết rồi tự thiêu, qua đó kích hoạt tiếng tụng của triệu hoán kinh.","anchor":"Xoạt một tiếng, tấm này da thú bay vào năng lượng màu đen trong biển, rơi vào cốt trên đài, nhuộm dần trên cái kia sợi huyết sau, ầm một tiếng tự động thiêu đốt."}]},"nguon":["@c1453"]},{"id":"hoang-kim-truong-thuong-cua-an-lan","name":"Hoàng Kim trường thương của An Lan","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["An Lan"],"trangThai":"Uy thế được tái hiện","blurb":"Binh khí của An Lan có uy thế được Cốt đài triệu hoán tái hiện để xuyên giới can thiệp vào trận chiến.","detail":"Trong lần xuất hiện này, bản thể trường thương không giáng lâm. Uy thế của nó được bàn tay An Lan nắm giữ, đâm xuyên và ghim bàn tay Táng sĩ giữa hư không.","phanLoaiPhu":"Trường thương","hinhDang":"Trường thương màu vàng kim","uyLuc":"Đâm xuyên bàn tay khổng lồ của Táng sĩ và ghim nó giữa hư không.","dacDiem":"Thứ xuất hiện tại chiến trường chỉ là uy thế tái hiện, không phải bản thể binh khí.","chuHienThoi":"An Lan","congNang":["Đâm xuyên và ghim bàn tay Táng sĩ giữa hư không tại @c1454."],"chuSoHuu":[{"ten":"An Lan","tuChuong":"@c1454","denChuong":"","cachCoDuoc":"Binh khí của An Lan","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1454","loai":"dùng","importance":"normal","giaiDoan":"Uy thế tái hiện","text":"Cốt đài tái hiện uy thế Hoàng Kim trường thương để bàn tay An Lan cầm lấy, đâm xuyên và ghim bàn tay Táng sĩ giữa hư không.","anchor":"này không phải cái kia cây trường thương bản thể, mà là uy thế tái hiện","phamCap":"Không rõ"}]},"capNhatToi":"@c1454","nguon":["@c1454"]},{"id":"hac-thach-truy","name":"Hắc thạch trụy","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"Đang được mang theo","blurb":"Một khối đá đen được cường giả tiền bối của Đế Tộc gia trì, có khả năng khắc chế pháp lực miễn dịch.","detail":"Hắc thạch trụy được Đại nhân trẻ tuổi Đế Tộc kích phát trong cuộc phục kích Thạch Hạo tại ách thổ. Ánh sáng từ vật này trung hòa pháp lực miễn dịch, khiến lợi thế mà Thạch Hạo dự định dùng trong đòn đánh bất ngờ không thể phát huy.","phanLoaiPhu":"Mặt dây chuyền bằng đá đen","nguonGoc":"Được cường giả tiền bối của Đế Tộc gia trì.","uyLuc":"Có thể trung hòa năng lực pháp lực miễn dịch của Thạch Hạo.","dacDiem":"Phát sáng khi được kích hoạt để hóa giải bí lực chuyên biệt.","congNang":["Trung hòa pháp lực miễn dịch khi được kích phát."],"chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc","chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1456","denChuong":"","cachCoDuoc":"Được cường giả tiền bối của Đế Tộc gia trì và giao mang theo.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1456","tabs":{"tienTrinh":[{"chuong":"@c1456","loai":"dùng","importance":"normal","giaiDoan":"Khắc chế pháp lực miễn dịch","text":"Hắc thạch trụy phát sáng trên người Đại nhân trẻ tuổi Đế Tộc và trung hòa pháp lực miễn dịch của Thạch Hạo.","anchor":"trên người có một khối hắc thạch trụy phát sáng, trung hoà này vừa làm dùng","phamCap":"Không rõ"}]},"nguon":["@c1456"]},{"id":"truong-dao-cua-de-toc-tuoi-tre-cuong-gia","name":"Trường đao của Đế Tộc tuổi trẻ cường giả","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"","soHuu":["Đại nhân trẻ tuổi Đế Tộc"],"trangThai":"đang được sử dụng","blurb":"Thanh trường đao có thân đặc biệt dài, được cao thủ trẻ tuổi Đế Tộc dùng để chém Thạch Hạo.","detail":"Trường đao phát ra đao khí cuồn cuộn bao phủ cương vực, có uy thế khiến sinh linh Trảm Ngã cảnh tuyệt vọng. Đòn đánh của nó bị Đại La kiếm thai cách không đối kích.","hinhDang":"Thân đao đặc biệt dài.","uyLuc":"Đao khí có thể quét ngang cương vực và khiến sinh linh Trảm Ngã cảnh tuyệt vọng.","dacDiem":"Tỏa ra thần uy huy hoàng và khí thế cực kỳ khiếp người.","chuHienThoi":"Đại nhân trẻ tuổi Đế Tộc","congNang":["Phóng đao khí bao phủ khoảng cách cực xa để chém giết mục tiêu."],"chuSoHuu":[{"ten":"Đại nhân trẻ tuổi Đế Tộc","tuChuong":"@c1457","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"capNhatToi":"@c1457","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1457","loai":"dùng","importance":"normal","giaiDoan":"Đối kích kiếm thai","phamCap":"","text":"Cao thủ trẻ tuổi Đế Tộc dùng trường đao tung đao khí bao trùm cương vực về phía Thạch Hạo, nhưng bị Đại La kiếm thai cách không đối kích.","anchor":"Đó là một thanh trường đao, huy hoàng thần uy, khiếp người cực điểm, đao này đặc biệt trường, này một đao oai để Trảm Ngã cảnh giới hết thảy sinh linh đều muốn tuyệt vọng, thực sự quá mạnh mẽ."}]},"nguon":["@c1457"]},{"id":"chiec-la-cua-truong-sinh-tien-thu","name":"Chiếc lá của Trường Sinh Tiên thụ","cn":"","category":"khac","categoryLabel":"Vật dẫn truy tung","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"đang được sử dụng","blurb":"Chiếc lá Thạch Hạo lấy được trong một lần truy kích Trường Sinh Tiên thụ, trên đó còn lưu dấu ấn khí tức nồng đậm.","detail":"Thạch Hạo dùng khí tức lưu trên chiếc lá để khóa chặt tung tích Trường Sinh Tiên thụ khi nó chui xuống tầng đất có khả năng ngăn cách cảm giác.","nguonGoc":"Thu được trong lần Thạch Hạo truy kích Trường Sinh Tiên thụ trước đó.","dacDiem":"Mang dấu ấn khí tức nồng đậm của Trường Sinh Tiên thụ.","chuHienThoi":"Thạch Hạo","congNang":["Giúp Thạch Hạo truy tung Trường Sinh Tiên thụ dưới lòng đất."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1457","denChuong":"","cachCoDuoc":"Lấy được trong một lần truy kích Trường Sinh Tiên thụ.","trangThai":"đang sở hữu"}],"capNhatToi":"@c1457","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1457","loai":"dùng","importance":"normal","giaiDoan":"Khóa dấu tiên dược","phamCap":"","text":"Thạch Hạo dùng dấu ấn khí tức còn lưu trên chiếc lá để khóa chặt Trường Sinh Tiên thụ và truy đuổi dưới lòng đất.","anchor":"Hắn không sợ mất dấu, bởi vì, ở trong tay của hắn có một chiếc lá, là trước kia truy kích này cây Trường Sinh thụ thì được, có một luồng nồng nặc dấu ấn khí tức."}]},"nguon":["@c1457"]},{"id":"truong-mau-cua-truyen-nhan-co-toc","name":"Trường mâu của truyền nhân Cô Tộc","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Chí tôn trẻ tuổi Cô Tộc"],"trangThai":"Nguyên vẹn","blurb":"Trường mâu được truyền nhân Cô Tộc phóng từ phía sau để tập kích Thạch Hạo. Binh khí xuyên qua đất trời nhưng bị Đại La kiếm thai chém bật.","detail":"Trường mâu được dùng trong cuộc truy đuổi Trường Sinh thụ dưới lòng đất. Đòn tập kích không ngăn được Thạch Hạo tiếp tục đuổi theo hòm gỗ mục.","uyLuc":"Có thể xuyên thủng đất trời khi được phóng ra.","chuHienThoi":"Chí tôn trẻ tuổi Cô Tộc","chuSoHuu":[{"ten":"Chí tôn trẻ tuổi Cô Tộc","tuChuong":"@c1458","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang sở hữu"}],"capNhatToi":"@c1458","tabs":{"tienTrinh":[{"chuong":"@c1458","loai":"dùng","importance":"normal","giaiDoan":"Tập kích Thạch Hạo","text":"Truyền nhân Cô Tộc phóng trường mâu xuyên qua đất trời để tập kích Thạch Hạo, nhưng binh khí bị Đại La kiếm thai chém bật.","anchor":"thời gian dài mâu bay ra, xuyên thủng đất trời","phamCap":"Không rõ"}]},"nguon":["@c1458"]},{"id":"quan-tai-hoa-da-cua-tang-si","name":"Quan tài hóa đá của Táng Sĩ","cn":"","category":"khac","categoryLabel":"Quan tài","phamCap":"Không rõ","soHuu":["Táng Sĩ trong quan tài hóa đá"],"trangThai":"Nứt vỡ","blurb":"Quan tài cổ xưa đã hóa đá nằm sâu trong chi mạch táng địa. Nó nứt vỡ khi Táng Sĩ bên trong bị đánh thức và lao ra truy sát Thạch Hạo.","detail":"Một bàn tay trắng bệch từ trong quan tài vươn ra chụp Thạch Hạo. Sau khi hắn tránh thoát, chủ nhân tỉnh dậy khiến quan tài hoàn toàn nứt vỡ.","hinhDang":"Quan tài cổ xưa đã hóa đá","dacDiem":"Chứa một Táng Sĩ ngủ say suốt thời gian dài.","chuHienThoi":"Táng Sĩ trong quan tài hóa đá","chuSoHuu":[{"ten":"Táng Sĩ trong quan tài hóa đá","tuChuong":"@c1458","denChuong":"@c1458","cachCoDuoc":"Nơi ngủ say","trangThai":"đã phá vỡ quan tài"}],"capNhatToi":"@c1458","tabs":{"tienTrinh":[{"chuong":"@c1458","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Nứt vỡ khi chủ nhân tỉnh dậy","text":"Quan tài hóa đá nứt vỡ hoàn toàn khi Táng Sĩ đang ngủ bên trong bị đánh thức và lao ra truy sát Thạch Hạo.","anchor":"phía sau cái kia chiếc quan tài triệt để nứt ra, một con sinh vật đáng sợ tránh ra","phamCap":"Không rõ"}]},"nguon":["@c1458"]},{"id":"truong-sinh-duoc-cua-thach-hao","name":"Trường Sinh dược của Thạch Hạo","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Tiên dược","phamCap":"Trường Sinh dược","soHuu":["Thạch Hạo"],"trangThai":"dang-co","blurb":"Cây Trường Sinh dược được Thạch Hạo mang tới khu vực Táng Uyên. Nó có thể dẫn tới thiên trân và táng bảo nhưng cũng sẽ chịu ảnh hưởng lớn khi tiến vào vực.","detail":"Trường Sinh dược có khả năng tiến vào Táng Uyên và dẫn người sở hữu tới những thiên trân hoặc táng bảo ẩn bên trong. Môi trường của Táng Uyên đồng thời gây ảnh hưởng đáng kể tới chính tiên dược.","phanLoaiPhu":"Trường Sinh dược","dacDiem":"Bị Táng Uyên ảnh hưởng khi tiến vào bên trong.","congNang":["Dẫn tới thiên trân và táng bảo trong Táng Uyên @c1460"],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1460","denChuong":"","cachCoDuoc":"Mang theo tới khu vực Táng Uyên","trangThai":"dang-co"}],"capNhatToi":"@c1460","tabs":{"tienTrinh":[{"chuong":"@c1460","loai":"xuất hiện","importance":"normal","giaiDoan":"Chuẩn bị tiến vào Táng Uyên","text":"Được xác nhận có khả năng dẫn tới thiên trân và táng bảo trong Táng Uyên, dù bản thân sẽ chịu ảnh hưởng tại đó.","anchor":"Trường Sinh dược có thể nhập Táng Uyên, có thể dẫn tới \"Thiên trân\" cùng \"Táng bảo\" các loại.","phamCap":"Trường Sinh dược"}]},"nguon":["@c1460"]},{"id":"tu-duoc-hinh-nguoi-chin-tang-than-hoan","name":"Tử dược hình người chín tầng thần hoàn","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Trường Sinh dược","phamCap":"Trường Sinh dược","soHuu":["Tam Tạng","Thần Minh"],"trangThai":"dang-co","blurb":"Tử dược màu tím có hình người, tỏa Tiên Đạo khí tức và được chín tầng thần hoàn bao quanh. Nó bị nghi là thuốc của cự phách dưỡng kê sâu trong Cổ Táng Vực.","detail":"Cây thuốc do nhóm Tam Tạng và Thần Minh mang tới để chuẩn bị tiến vào Táng Uyên. Hình dáng và khí tức khác thường của nó khiến Trường Sinh thụ suy đoán cây thuốc thuộc về một cự phách mạnh mẽ.","phanLoaiPhu":"Trường Sinh dược","hinhDang":"Hình người màu tím, bên ngoài có chín tầng thần hoàn.","nguonGoc":"Nghi thuộc về cự phách dưỡng kê ở nơi sâu nhất của Cổ Táng Vực.","dacDiem":"Tỏa Tiên Đạo khí tức và có chín tầng thần hoàn bao quanh.","chuHienThoi":"Nhóm Tam Tạng và Thần Minh","chuSoHuu":[{"ten":"Tam Tạng","tuChuong":"@c1460","denChuong":"","cachCoDuoc":"Cùng Thần Minh mang tới khu vực Táng Uyên","trangThai":"dang-co"},{"ten":"Thần Minh","tuChuong":"@c1460","denChuong":"","cachCoDuoc":"Cùng Tam Tạng mang tới khu vực Táng Uyên","trangThai":"dang-co"}],"capNhatToi":"@c1460","tabs":{"tienTrinh":[{"chuong":"@c1460","loai":"xuất hiện","importance":"normal","giaiDoan":"Được mang tới Táng Uyên","text":"Xuất hiện dưới hình dạng một cây thuốc màu tím hình người, bên ngoài có chín tầng thần hoàn và bị nghi thuộc về cự phách dưỡng kê.","anchor":"nó bên ngoài cơ thể có chín đạo thần hoàn, một đạo trùm vào một đạo, hình thành chín tầng vầng sáng","phamCap":"Trường Sinh dược"}]},"nguon":["@c1460"]},{"id":"khoi-mau-kho-tren-van-quan-tai-tu-kim","name":"Khối máu khô trên ván quan tài tử kim","cn":"","aliases":[],"category":"khac","categoryLabel":"Táng bảo","phamCap":"Không rõ","soHuu":[],"trangThai":"được bày tại phố chợ","blurb":"Khối máu đã khô héo và thiếu linh tính, được đặt trên một tấm ván quan tài tử kim. Trường Sinh thụ nhận định nó từng rơi ra từ một đại nhân vật vô thượng.","detail":"Dù linh tính đã hao hụt, khối máu khô vẫn có tác dụng lớn trong táng địa và được xem là một loại táng bảo đáng giá đối với Táng Sĩ.","phanLoaiPhu":"Táng bảo","nguonGoc":"Máu từng rơi ra từ một đại nhân vật vô thượng.","dacDiem":"Đã khô héo và thiếu linh tính nhưng vẫn hữu dụng trong táng địa.","congNang":["Có tác dụng lớn đối với Táng Sĩ trong táng địa @c1460"],"capNhatToi":"@c1460","tabs":{"tienTrinh":[{"chuong":"@c1460","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhận diện tại phố chợ","text":"Được Trường Sinh thụ nhận định là máu từng rơi ra từ một đại nhân vật vô thượng và vẫn có giá trị đối với Táng Sĩ.","anchor":"đây là một vị vô thượng đại nhân vật đã từng rơi ra huyết","phamCap":"Không rõ"}]},"nguon":["@c1460"]},{"id":"van-quan-tai-muc-nat-tu-truong-sinh-thu","name":"Ván quan tài mục nát từ Trường Sinh thụ","cn":"","aliases":[],"category":"khac","categoryLabel":"Táng bảo","phamCap":"Không rõ","soHuu":[],"trangThai":"được bày tại phố chợ","blurb":"Một tấm ván quan tài bề ngoài đã mục nát nhưng vốn là bộ phận của Trường Sinh thụ. Trong quá khứ xa xưa, nó từng chứa linh tính cực kỳ mạnh.","detail":"Trường Sinh thụ nhận ra bản chất phi phàm của tấm ván giữa những vật phẩm kỳ dị tại phố chợ. Lai lịch này khiến món đồ tưởng như phế vật được xác định là táng bảo quý hiếm.","phanLoaiPhu":"Táng bảo","vatLieu":"Bộ phận của Trường Sinh thụ","nguonGoc":"Từng là một phần của Trường Sinh thụ.","dacDiem":"Bề ngoài mục nát nhưng từng chứa linh tính cực mạnh.","capNhatToi":"@c1460","tabs":{"tienTrinh":[{"chuong":"@c1460","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhận diện tại phố chợ","text":"Được xác định là bộ phận của Trường Sinh thụ dù bề ngoài đã mục nát.","anchor":"tuy rằng mục nát, thế nhưng nó nhưng là Trường Sinh thụ bộ phận","phamCap":"Không rõ"}]},"nguon":["@c1460"]}]};
